    public class Trade : RustPlugin
    {        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006F\u006E\u0073\u0074 \u0073\u0074\u0072\u0069\u006E\u0067 \u0070\u0072\u0065f\u0061\u0062\u0045\u006E\u0074\u0069\u0074\u0079 = "\u0061\u0073\u0073\u0065\u0074\u0073/\u0062\u0075\u006E\u0064\u006C\u0065\u0064/\u0070\u0072\u0065f\u0061\u0062\u0073/\u0073\u0074\u0061\u0074\u0069\u0063/\u0077\u0061\u006C\u006C.f\u0072\u0061\u006D\u0065.\u0073\u0068\u006F\u0070f\u0072\u006F\u006E\u0074.\u006D\u0065\u0074\u0061\u006C.\u0073\u0074\u0061\u0074\u0069\u0063.\u0070\u0072\u0065f\u0061\u0062";        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006F\u006E\u0073\u0074 \u0073\u0074\u0072\u0069\u006E\u0067 \u0070\u0072\u0065f\u0061\u0062\u0054\u0065\u0073\u0074\u0050\u006C\u0061\u0079\u0065\u0072 = "\u0061\u0073\u0073\u0065\u0074\u0073/\u0070\u0072\u0065f\u0061\u0062\u0073/\u0070\u006C\u0061\u0079\u0065\u0072/\u0070\u006C\u0061\u0079\u0065\u0072.\u0070\u0072\u0065f\u0061\u0062";        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0062\u006F\u006F\u006C \u0069\u0073\u0054\u0072\u0061\u0064\u0069\u006E\u0067\u0045\u006E\u0074\u0069\u0074\u0079(\u0042\u0061\u0073\u0065\u0045\u006E\u0074\u0069\u0074\u0079 \u0065\u006E\u0074\u0069\u0074\u0079) => \u0065\u006E\u0074\u0069\u0074\u0079 != \u006E\u0075\u006C\u006C && \u0065\u006E\u0074\u0069\u0074\u0079.\u006E\u0061\u006D\u0065 == \u006B\u0065\u0079\u004E\u0061\u006D\u0065;        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006F\u006E\u0073\u0074 \u0073\u0074\u0072\u0069\u006E\u0067 \u006B\u0065\u0079\u004E\u0061\u006D\u0065 = "\u0054\u0072\u0061\u0064\u0065\u0050\u006C\u0075\u0067\u0069\u006E\u0046\u0072\u006F\u006E\u0074";        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0054\u0072\u0061\u0064\u0065 \u0070\u006C\u0075\u0067\u0069\u006E;        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0062\u006F\u006F\u006C \u0074\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0046\u006C\u0061\u0067;        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0049\u006E\u0069\u0074()        {            \u0070\u006C\u0075\u0067\u0069\u006E = \u0074\u0068\u0069\u0073;            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0063\u006F\u006D\u006D\u0061\u006E\u0064 \u0069\u006E \u0063\u006F\u006Ef\u0069\u0067.\u0063\u006F\u006D\u006D\u0061\u006E\u0064)            {                \u0063\u006D\u0064.\u0041\u0064\u0064\u0043\u0068\u0061\u0074\u0043\u006F\u006D\u006D\u0061\u006E\u0064(\u0063\u006F\u006D\u006D\u0061\u006E\u0064, \u0074\u0068\u0069\u0073, \u006E\u0061\u006D\u0065\u006Ff(\u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u0068\u0061\u0074));                \u0063\u006D\u0064.\u0041\u0064\u0064\u0043\u006F\u006E\u0073\u006F\u006C\u0065\u0043\u006F\u006D\u006D\u0061\u006E\u0064(\u0063\u006F\u006D\u006D\u0061\u006E\u0064, \u0074\u0068\u0069\u0073, \u006E\u0061\u006D\u0065\u006Ff(\u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u006F\u006E\u0073\u006F\u006C\u0065));            }            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0063\u006F\u006D\u006D\u0061\u006E\u0064 \u0069\u006E \u0063\u006F\u006Ef\u0069\u0067.\u0061\u0063\u0063\u0065\u0070\u0074\u0043\u006F\u006D\u006D\u0061\u006E\u0064)            {                \u0063\u006D\u0064.\u0041\u0064\u0064\u0043\u0068\u0061\u0074\u0043\u006F\u006D\u006D\u0061\u006E\u0064(\u0063\u006F\u006D\u006D\u0061\u006E\u0064, \u0074\u0068\u0069\u0073, \u006E\u0061\u006D\u0065\u006Ff(\u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u0068\u0061\u0074));                \u0063\u006D\u0064.\u0041\u0064\u0064\u0043\u006F\u006E\u0073\u006F\u006C\u0065\u0043\u006F\u006D\u006D\u0061\u006E\u0064(\u0063\u006F\u006D\u006D\u0061\u006E\u0064, \u0074\u0068\u0069\u0073, \u006E\u0061\u006D\u0065\u006Ff(\u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u006F\u006E\u0073\u006F\u006C\u0065));            }            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0063\u006F\u006D\u006D\u0061\u006E\u0064 \u0069\u006E \u0063\u006F\u006Ef\u0069\u0067.\u0064\u0065\u0063\u006C\u0069\u006E\u0065\u0043\u006F\u006D\u006D\u0061\u006E\u0064)            {                \u0063\u006D\u0064.\u0041\u0064\u0064\u0043\u0068\u0061\u0074\u0043\u006F\u006D\u006D\u0061\u006E\u0064(\u0063\u006F\u006D\u006D\u0061\u006E\u0064, \u0074\u0068\u0069\u0073, \u006E\u0061\u006D\u0065\u006Ff(\u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u0068\u0061\u0074));                \u0063\u006D\u0064.\u0041\u0064\u0064\u0043\u006F\u006E\u0073\u006F\u006C\u0065\u0043\u006F\u006D\u006D\u0061\u006E\u0064(\u0063\u006F\u006D\u006D\u0061\u006E\u0064, \u0074\u0068\u0069\u0073, \u006E\u0061\u006D\u0065\u006Ff(\u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u006F\u006E\u0073\u006F\u006C\u0065));            }            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0076\u0061\u006C\u0075\u0065 \u0069\u006E \u0063\u006F\u006Ef\u0069\u0067.\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073)            {                \u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E.\u0052\u0065\u0067\u0069\u0073\u0074\u0065\u0072\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E(\u0076\u0061\u006C\u0075\u0065.\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E, \u0074\u0068\u0069\u0073);            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u004F\u006E\u0053\u0065\u0072\u0076\u0065\u0072\u0049\u006E\u0069\u0074\u0069\u0061\u006C\u0069\u007A\u0065\u0064()        {            \u004C\u006F\u0061\u0064\u0044\u0061\u0074\u0061();        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0055\u006E\u006C\u006F\u0061\u0064()        {            \u0053\u0061\u0076\u0065\u0044\u0061\u0074\u0061();        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u004F\u006E\u0053\u0068\u006F\u0070\u0043\u006F\u006D\u0070\u006C\u0065\u0074\u0065\u0054\u0072\u0061\u0064\u0065(\u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074 \u0065\u006E\u0074\u0069\u0074\u0079)        {            \u0069f (\u0069\u0073\u0054\u0072\u0061\u0064\u0069\u006E\u0067\u0045\u006E\u0074\u0069\u0074\u0079(\u0065\u006E\u0074\u0069\u0074\u0079) == f\u0061\u006C\u0073\u0065)            {                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0069f (\u0063\u006F\u006Ef\u0069\u0067.\u006C\u006F\u0067\u0054\u0072\u0061\u0064\u0065 == \u0074\u0072\u0075\u0065)            {                \u004C\u006F\u0067\u0054\u0072\u0061\u0064\u0065(\u0065\u006E\u0074\u0069\u0074\u0079);            }            \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00721 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0076\u0065\u006E\u0064\u006F\u0072\u0050\u006C\u0061\u0079\u0065\u0072;            \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00722 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072;            \u0076\u0061\u0072 \u0064\u0061\u0074\u00611 = \u0044\u0061\u0074\u0061.\u0047\u0065\u0074(\u0070\u006C\u0061\u0079\u0065\u00721.\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067, \u0074\u0072\u0075\u0065);            \u0076\u0061\u0072 \u0064\u0061\u0074\u00612 = \u0044\u0061\u0074\u0061.\u0047\u0065\u0074(\u0070\u006C\u0061\u0079\u0065\u00722.\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067, \u0074\u0072\u0075\u0065);            \u0064\u0061\u0074\u00611.\u006C\u0061\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0055\u0073\u0065 = \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077;            \u0064\u0061\u0074\u00612.\u006C\u0061\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0055\u0073\u0065 = \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077;            \u0052\u0075\u006E\u0045ff\u0065\u0063\u0074(\u0070\u006C\u0061\u0079\u0065\u00721.\u0074\u0072\u0061\u006E\u0073f\u006F\u0072\u006D.\u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E, \u0063\u006F\u006Ef\u0069\u0067.\u0065ff\u0065\u0063\u0074\u004F\u006E\u0043\u006F\u006D\u0070\u006C\u0065\u0074\u0065\u0054\u0072\u0061\u0064\u0065, \u0070\u006C\u0061\u0079\u0065\u00721);            \u0052\u0075\u006E\u0045ff\u0065\u0063\u0074(\u0070\u006C\u0061\u0079\u0065\u00722.\u0074\u0072\u0061\u006E\u0073f\u006F\u0072\u006D.\u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E, \u0063\u006F\u006Ef\u0069\u0067.\u0065ff\u0065\u0063\u0074\u004F\u006E\u0043\u006F\u006D\u0070\u006C\u0065\u0074\u0065\u0054\u0072\u0061\u0064\u0065, \u0070\u006C\u0061\u0079\u0065\u00722);            \u004E\u0065\u0078\u0074\u0054\u0069\u0063\u006B(() =>            {                \u0069f (\u0065\u006E\u0074\u0069\u0074\u0079.\u0049\u0073\u0056\u0061\u006C\u0069\u0064() == \u0074\u0072\u0075\u0065 && \u0065\u006E\u0074\u0069\u0074\u0079.\u0048\u0061\u0073\u0046\u006C\u0061\u0067(\u0042\u0061\u0073\u0065\u0045\u006E\u0074\u0069\u0074\u0079.\u0046\u006C\u0061\u0067\u0073.\u0052\u0065\u0073\u0065\u0072\u0076\u0065\u00643) == f\u0061\u006C\u0073\u0065)                {                    \u0065\u006E\u0074\u0069\u0074\u0079.\u004B\u0069\u006C\u006C();                }            });        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u004F\u006E\u004C\u006F\u006F\u0074\u0045\u006E\u0074\u0069\u0074\u0079\u0045\u006E\u0064(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072, \u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074 \u0065\u006E\u0074\u0069\u0074\u0079)        {            \u0069f (\u0069\u0073\u0054\u0072\u0061\u0064\u0069\u006E\u0067\u0045\u006E\u0074\u0069\u0074\u0079(\u0065\u006E\u0074\u0069\u0074\u0079) == f\u0061\u006C\u0073\u0065)            {                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u004E\u0065\u0078\u0074\u0054\u0069\u0063\u006B(() =>            {                \u0069f (\u0065\u006E\u0074\u0069\u0074\u0079.\u0049\u0073\u0056\u0061\u006C\u0069\u0064() == \u0074\u0072\u0075\u0065 && \u0065\u006E\u0074\u0069\u0074\u0079.\u0048\u0061\u0073\u0046\u006C\u0061\u0067(\u0042\u0061\u0073\u0065\u0045\u006E\u0074\u0069\u0074\u0079.\u0046\u006C\u0061\u0067\u0073.\u0052\u0065\u0073\u0065\u0072\u0076\u0065\u00643) == f\u0061\u006C\u0073\u0065)                {                    \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00721 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0076\u0065\u006E\u0064\u006F\u0072\u0050\u006C\u0061\u0079\u0065\u0072;                    \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00722 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072;                    \u0065\u006E\u0074\u0069\u0074\u0079.\u0052\u0065\u0074\u0075\u0072\u006E\u0050\u006C\u0061\u0079\u0065\u0072\u0049\u0074\u0065\u006D\u0073(\u0070\u006C\u0061\u0079\u0065\u00721);                    \u0065\u006E\u0074\u0069\u0074\u0079.\u0052\u0065\u0074\u0075\u0072\u006E\u0050\u006C\u0061\u0079\u0065\u0072\u0049\u0074\u0065\u006D\u0073(\u0070\u006C\u0061\u0079\u0065\u00722);                    \u0065\u006E\u0074\u0069\u0074\u0079.\u004B\u0069\u006C\u006C();                }            });        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u006F\u0062\u006A\u0065\u0063\u0074 \u004F\u006E\u0045\u006E\u0074\u0069\u0074\u0079\u0056\u0069\u0073\u0069\u0062\u0069\u006C\u0069\u0074\u0079\u0043\u0068\u0065\u0063\u006B(\u0042\u0061\u0073\u0065\u0045\u006E\u0074\u0069\u0074\u0079 \u0065\u006E\u0074, \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072, \u0075\u0069\u006E\u0074 \u0069\u0064, \u0073\u0074\u0072\u0069\u006E\u0067 \u0064\u0065\u0062\u0075\u0067\u004E\u0061\u006D\u0065,            f\u006C\u006F\u0061\u0074 \u006D\u0061\u0078\u0069\u006D\u0075\u006D\u0044\u0069\u0073\u0074\u0061\u006E\u0063\u0065)        {            \u0069f (\u0069\u0073\u0054\u0072\u0061\u0064\u0069\u006E\u0067\u0045\u006E\u0074\u0069\u0074\u0079(\u0065\u006E\u0074) == \u0074\u0072\u0075\u0065)            {                \u0072\u0065\u0074\u0075\u0072\u006E \u0074\u0072\u0075\u0065;            }            \u0072\u0065\u0074\u0075\u0072\u006E \u006E\u0075\u006C\u006C;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u006F\u006E\u0073\u006F\u006C\u0065(\u0043\u006F\u006E\u0073\u006F\u006C\u0065\u0053\u0079\u0073\u0074\u0065\u006D.\u0041\u0072\u0067 \u0061\u0072\u0067)        {            \u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u0068\u0061\u0074(\u0061\u0072\u0067.\u0050\u006C\u0061\u0079\u0065\u0072(), \u0061\u0072\u0067.\u0063\u006D\u0064.\u0046\u0075\u006C\u006C\u004E\u0061\u006D\u0065, \u0061\u0072\u0067.\u0041\u0072\u0067\u0073);        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0063\u006D\u0064\u0043\u006F\u006E\u0074\u0072\u006F\u006C\u0043\u0068\u0061\u0074(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072, \u0073\u0074\u0072\u0069\u006E\u0067 \u0063\u006F\u006D\u006D\u0061\u006E\u0064, \u0073\u0074\u0072\u0069\u006E\u0067[] \u0061\u0072\u0067\u0073)        {            \u0076\u0061\u0072 \u0070\u0065\u0072\u006D = \u0047\u0065\u0074\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E(\u0070\u006C\u0061\u0079\u0065\u0072.\u0075\u0073\u0065\u0072\u0049\u0044, \u0063\u006F\u006Ef\u0069\u0067.\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073);            \u0069f (\u0070\u0065\u0072\u006D == \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0069f (\u0048\u0061\u0076\u0065\u0041\u0062\u0069\u006C\u0069\u0074\u0079\u0046\u006F\u0072\u0054\u0072\u0061\u0064\u0069\u006E\u0067(\u0070\u006C\u0061\u0079\u0065\u0072) == f\u0061\u006C\u0073\u0065)            {                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0069f (\u0063\u006F\u006Ef\u0069\u0067.\u0061\u0063\u0063\u0065\u0070\u0074\u0043\u006F\u006D\u006D\u0061\u006E\u0064.\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0073(\u0063\u006F\u006D\u006D\u0061\u006E\u0064))            {                \u0041\u0063\u0063\u0065\u0070\u0074\u004F\u0072\u0043\u0061\u006E\u0063\u0065\u006C\u0052\u0065\u0071\u0075\u0065\u0073\u0074(\u0070\u006C\u0061\u0079\u0065\u0072, f\u0061\u006C\u0073\u0065);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0069f (\u0063\u006F\u006Ef\u0069\u0067.\u0064\u0065\u0063\u006C\u0069\u006E\u0065\u0043\u006F\u006D\u006D\u0061\u006E\u0064.\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0073(\u0063\u006F\u006D\u006D\u0061\u006E\u0064))            {                \u0041\u0063\u0063\u0065\u0070\u0074\u004F\u0072\u0043\u0061\u006E\u0063\u0065\u006C\u0052\u0065\u0071\u0075\u0065\u0073\u0074(\u0070\u006C\u0061\u0079\u0065\u0072, \u0074\u0072\u0075\u0065);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u0061\u0063\u0074\u0069\u006F\u006E = \u0061\u0072\u0067\u0073?.\u004C\u0065\u006E\u0067\u0074\u0068 > 0 ? \u0061\u0072\u0067\u0073[0] : "\u0075\u006E\u006B\u006E\u006F\u0077\u006E";            \u0073\u0077\u0069\u0074\u0063\u0068 (\u0061\u0063\u0074\u0069\u006F\u006E.\u0054\u006F\u004C\u006F\u0077\u0065\u0072())            {                \u0063\u0061\u0073\u0065 "\u0061\u0063\u0063\u0065\u0070\u0074":                \u0063\u0061\u0073\u0065 "+":                \u0063\u0061\u0073\u0065 "\u0079\u0065\u0073":                \u0063\u0061\u0073\u0065 "\u0079":                \u0063\u0061\u0073\u0065 "\u0061":                    \u0041\u0063\u0063\u0065\u0070\u0074\u004F\u0072\u0043\u0061\u006E\u0063\u0065\u006C\u0052\u0065\u0071\u0075\u0065\u0073\u0074(\u0070\u006C\u0061\u0079\u0065\u0072, f\u0061\u006C\u0073\u0065);                    \u0072\u0065\u0074\u0075\u0072\u006E;                \u0063\u0061\u0073\u0065 "\u0063\u0061\u006E\u0063\u0065\u006C":                \u0063\u0061\u0073\u0065 "-":                \u0063\u0061\u0073\u0065 "\u006E\u006F":                \u0063\u0061\u0073\u0065 "\u006E":                \u0063\u0061\u0073\u0065 "\u0063":                    \u0041\u0063\u0063\u0065\u0070\u0074\u004F\u0072\u0043\u0061\u006E\u0063\u0065\u006C\u0052\u0065\u0071\u0075\u0065\u0073\u0074(\u0070\u006C\u0061\u0079\u0065\u0072, \u0074\u0072\u0075\u0065);                    \u0072\u0065\u0074\u0075\u0072\u006E;                \u0063\u0061\u0073\u0065 "\u0074\u0065\u0073\u0074":                    \u0069f (\u0070\u006C\u0061\u0079\u0065\u0072.\u0049\u0073\u0041\u0064\u006D\u0069\u006E == \u0074\u0072\u0075\u0065)                    {                        \u0054\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065(\u0070\u006C\u0061\u0079\u0065\u0072);                    }                    \u0072\u0065\u0074\u0075\u0072\u006E;                \u0064\u0065f\u0061\u0075\u006C\u0074:                    \u0053\u0065\u006E\u0064\u0054\u0072\u0061\u0064\u0065\u0052\u0065\u0071\u0075\u0065\u0073\u0074(\u0070\u006C\u0061\u0079\u0065\u0072, \u0061\u0063\u0074\u0069\u006F\u006E, \u0070\u0065\u0072\u006D.\u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E);                    \u0072\u0065\u0074\u0075\u0072\u006E;            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0053\u0065\u006E\u0064\u0054\u0072\u0061\u0064\u0065\u0052\u0065\u0071\u0075\u0065\u0073\u0074(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0073\u0065\u006E\u0064\u0065\u0072, \u0073\u0074\u0072\u0069\u006E\u0067 \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072\u0053\u0074\u0072\u0069\u006E\u0067, \u0069\u006E\u0074 \u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E)        {            \u0076\u0061\u0072 \u0063\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074 = \u0073\u0065\u006E\u0064\u0065\u0072.\u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0050\u0065\u006E\u0064\u0069\u006E\u0067\u0054\u0072\u0061\u0064\u0065>();            \u0069f (\u0063\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074 != \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0073\u0065\u006E\u0064\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0041\u006C\u0072\u0065\u0061\u0064\u0079\u0050\u0065\u006E\u0064\u0069\u006E\u0067);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u0064\u0061\u0074\u0061 = \u0044\u0061\u0074\u0061.\u0047\u0065\u0074(\u0073\u0065\u006E\u0064\u0065\u0072.\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067, \u0074\u0072\u0075\u0065);            \u0076\u0061\u0072 \u0070\u0061\u0073\u0073\u0065\u0064 = (\u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077 - \u0064\u0061\u0074\u0061.\u006C\u0061\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0055\u0073\u0065).\u0054\u006F\u0074\u0061\u006C\u0053\u0065\u0063\u006F\u006E\u0064\u0073;            \u0076\u0061\u0072 \u006C\u0065f\u0074\u0053\u0065\u0063\u006F\u006E\u0064\u0073 = \u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E - \u0070\u0061\u0073\u0073\u0065\u0064;            \u0069f (\u006C\u0065f\u0074\u0053\u0065\u0063\u006F\u006E\u0064\u0073 > 0)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0073\u0065\u006E\u0064\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0043\u006F\u006F\u006C\u0064\u006F\u0077\u006E, "{\u0073\u0065\u0063\u006F\u006E\u0064\u0073}", \u006C\u0065f\u0074\u0053\u0065\u0063\u006F\u006E\u0064\u0073.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067("0.0"));                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u0074\u0061\u0072\u0067\u0065\u0074 = \u0046\u0069\u006E\u0064\u0050\u006C\u0061\u0079\u0065\u0072(\u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072\u0053\u0074\u0072\u0069\u006E\u0067);            \u0069f (\u0074\u0061\u0072\u0067\u0065\u0074 \u0069\u0073 \u0073\u0074\u0072\u0069\u006E\u0067)            {                \u0076\u0061\u0072 \u0074\u0065\u0078\u0074 = \u0074\u0061\u0072\u0067\u0065\u0074.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();                \u0069f (\u0074\u0065\u0078\u0074 == \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072\u0053\u0074\u0072\u0069\u006E\u0067)                {                    \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0073\u0065\u006E\u0064\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u004E\u006F\u0050\u006C\u0061\u0079\u0065\u0072\u0073, "{\u006E\u0061\u006D\u0065}", \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072\u0053\u0074\u0072\u0069\u006E\u0067);                    \u0072\u0065\u0074\u0075\u0072\u006E;                }                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0073\u0065\u006E\u0064\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u004D\u0075\u006C\u0074\u0069\u0070\u006C\u0065\u0050\u006C\u0061\u0079\u0065\u0072\u0073, "{\u006C\u0069\u0073\u0074}", \u0074\u0065\u0078\u0074);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072 = \u0074\u0061\u0072\u0067\u0065\u0074 \u0061\u0073 \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072;            \u0069f (\u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072 == \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0073\u0065\u006E\u0064\u0065\u0072, "\u0045\u0072\u0072\u006F\u0072: \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072 == \u006E\u0075\u006C\u006C");                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u0070\u0065\u006E\u0064\u0069\u006E\u0067\u0053\u0063\u0072\u0069\u0070\u0074 = \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072.\u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0050\u0065\u006E\u0064\u0069\u006E\u0067\u0054\u0072\u0061\u0064\u0065>();            \u0069f (\u0070\u0065\u006E\u0064\u0069\u006E\u0067\u0053\u0063\u0072\u0069\u0070\u0074 != \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0073\u0065\u006E\u0064\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0041\u006C\u0072\u0065\u0061\u0064\u0079\u0050\u0065\u006E\u0064\u0069\u006E\u0067);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072.\u0067\u0061\u006D\u0065\u004F\u0062\u006A\u0065\u0063\u0074.\u0041\u0064\u0064\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0050\u0065\u006E\u0064\u0069\u006E\u0067\u0054\u0072\u0061\u0064\u0065>().\u0053\u0065\u0074\u0075\u0070(\u0073\u0065\u006E\u0064\u0065\u0072);            \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0073\u0065\u006E\u0064\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0053\u0065\u006E\u0074, "{\u006E\u0061\u006D\u0065}", \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065);            \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0052\u0065\u0063\u0065\u0069\u0076\u0065\u0064, "{\u006E\u0061\u006D\u0065}", \u0073\u0065\u006E\u0064\u0065\u0072.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065);        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0041\u0063\u0063\u0065\u0070\u0074\u004F\u0072\u0043\u0061\u006E\u0063\u0065\u006C\u0052\u0065\u0071\u0075\u0065\u0073\u0074(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u00721, \u0062\u006F\u006F\u006C \u0063\u0061\u006E\u0063\u0065\u006C)        {            \u0076\u0061\u0072 \u0073\u0063\u0072\u0069\u0070\u0074 = \u0070\u006C\u0061\u0079\u0065\u00721.\u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0050\u0065\u006E\u0064\u0069\u006E\u0067\u0054\u0072\u0061\u0064\u0065>();            \u0069f (\u0073\u0063\u0072\u0069\u0070\u0074 == \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u00721, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u004E\u006F\u0050\u0065\u006E\u0064\u0069\u006E\u0067);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00722 = \u0073\u0063\u0072\u0069\u0070\u0074.\u0063\u0061\u006C\u006C\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072;            \u0055\u006E\u0069\u0074\u0079\u0045\u006E\u0067\u0069\u006E\u0065.\u004F\u0062\u006A\u0065\u0063\u0074.\u0044\u0065\u0073\u0074\u0072\u006F\u0079(\u0073\u0063\u0072\u0069\u0070\u0074);            \u0069f (\u0063\u0061\u006E\u0063\u0065\u006C == \u0074\u0072\u0075\u0065 || \u0048\u0061\u0076\u0065\u0041\u0062\u0069\u006C\u0069\u0074\u0079\u0046\u006F\u0072\u0054\u0072\u0061\u0064\u0069\u006E\u0067(\u0070\u006C\u0061\u0079\u0065\u00721) == f\u0061\u006C\u0073\u0065 || \u0048\u0061\u0076\u0065\u0041\u0062\u0069\u006C\u0069\u0074\u0079\u0046\u006F\u0072\u0054\u0072\u0061\u0064\u0069\u006E\u0067(\u0070\u006C\u0061\u0079\u0065\u00722) == f\u0061\u006C\u0073\u0065)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u00721, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0054\u0072\u0061\u0064\u0065\u0043\u0061\u006E\u0063\u0065\u006C\u006C\u0065\u0064);                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u00722, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0054\u0072\u0061\u0064\u0065\u0043\u0061\u006E\u0063\u0065\u006C\u006C\u0065\u0064);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0069f (\u0070\u006C\u0061\u0079\u0065\u00722 == \u006E\u0075\u006C\u006C)            {                \u0072\u0065\u0074\u0075\u0072\u006E;            }                        \u0042\u0065\u0067\u0069\u006E\u0054\u0072\u0061\u0064\u0065(\u0070\u006C\u0061\u0079\u0065\u00721, \u0070\u006C\u0061\u0079\u0065\u00722);        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0062\u006F\u006F\u006C \u0048\u0061\u0076\u0065\u0041\u0062\u0069\u006C\u0069\u0074\u0079\u0046\u006F\u0072\u0054\u0072\u0061\u0064\u0069\u006E\u0067(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072)        {            \u0069f (\u0070\u006C\u0061\u0079\u0065\u0072.\u0043\u0061\u006E\u0042\u0075\u0069\u006C\u0064() == f\u0061\u006C\u0073\u0065 && \u0063\u006F\u006Ef\u0069\u0067.\u0062\u006C\u006F\u0063\u006B\u0049\u006E\u0042\u0075\u0069\u006C\u0064\u0069\u006E\u0067\u0050\u0072\u0069\u0076\u0069\u006C\u0065\u0067\u0065 == \u0074\u0072\u0075\u0065)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0043\u0061\u006E\u0074\u0052\u0069\u0067\u0068\u0074\u004E\u006F\u0077);                \u0072\u0065\u0074\u0075\u0072\u006E f\u0061\u006C\u0073\u0065;            }                        \u0069f (\u0063\u006F\u006Ef\u0069\u0067.\u0062\u006C\u006F\u0063\u006B\u0049\u006E\u0052\u0061\u0069\u0064\u0062\u006C\u006F\u0063\u006B == \u0074\u0072\u0075\u0065 && \u0049\u006E\u0052\u0061\u0069\u0064\u0042\u006C\u006F\u0063\u006B(\u0070\u006C\u0061\u0079\u0065\u0072) == \u0074\u0072\u0075\u0065)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0043\u0061\u006E\u0074\u0052\u0069\u0067\u0068\u0074\u004E\u006F\u0077);                \u0072\u0065\u0074\u0075\u0072\u006E f\u0061\u006C\u0073\u0065;            }            \u0076\u0061\u0072 \u006D\u0065\u0073\u0073\u0061\u0067\u0065 = \u0043\u0061\u006E\u0055\u0073\u0065\u0054\u0072\u0061\u0064\u0065(\u0070\u006C\u0061\u0079\u0065\u0072);            \u0069f (\u0073\u0074\u0072\u0069\u006E\u0067.\u0049\u0073\u004E\u0075\u006C\u006C\u004F\u0072\u0045\u006D\u0070\u0074\u0079(\u006D\u0065\u0073\u0073\u0061\u0067\u0065) == f\u0061\u006C\u0073\u0065)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u0072, \u006D\u0065\u0073\u0073\u0061\u0067\u0065);                \u0072\u0065\u0074\u0075\u0072\u006E f\u0061\u006C\u0073\u0065;            }            \u0072\u0065\u0074\u0075\u0072\u006E \u0074\u0072\u0075\u0065;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0042\u0065\u0067\u0069\u006E\u0054\u0072\u0061\u0064\u0065(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u00721, \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u00722)        {            \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u00721, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0054\u0072\u0061\u0064\u0065\u0042\u0065\u0067\u0069\u006E\u0073, "{\u006E\u0061\u006D\u00651}", \u0070\u006C\u0061\u0079\u0065\u00721.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065, "{\u006E\u0061\u006D\u00652}", \u0070\u006C\u0061\u0079\u0065\u00722.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065);            \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u00722, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0054\u0072\u0061\u0064\u0065\u0042\u0065\u0067\u0069\u006E\u0073, "{\u006E\u0061\u006D\u00651}", \u0070\u006C\u0061\u0079\u0065\u00721.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065, "{\u006E\u0061\u006D\u00652}", \u0070\u006C\u0061\u0079\u0065\u00722.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065);            \u0076\u0061\u0072 \u0070\u0065\u0072\u006D1 = \u0047\u0065\u0074\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E(\u0070\u006C\u0061\u0079\u0065\u00721.\u0075\u0073\u0065\u0072\u0049\u0044, \u0063\u006F\u006Ef\u0069\u0067.\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073);            \u0076\u0061\u0072 \u0070\u0065\u0072\u006D2 = \u0047\u0065\u0074\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E(\u0070\u006C\u0061\u0079\u0065\u00722.\u0075\u0073\u0065\u0072\u0049\u0044, \u0063\u006F\u006Ef\u0069\u0067.\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073);            \u0069f (\u0070\u0065\u0072\u006D1 == \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u00721, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0069f (\u0070\u0065\u0072\u006D2 == \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0070\u006C\u0061\u0079\u0065\u00722, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E);                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u006D\u0061\u0078\u0053\u0069\u007A\u0065 = \u0070\u0065\u0072\u006D1.\u0073\u0069\u007A\u0065 > \u0070\u0065\u0072\u006D2.\u0073\u0069\u007A\u0065 ? \u0070\u0065\u0072\u006D1.\u0073\u0069\u007A\u0065 : \u0070\u0065\u0072\u006D2.\u0073\u0069\u007A\u0065;            \u0069f (\u006D\u0061\u0078\u0053\u0069\u007A\u0065 > 12)            {                \u006D\u0061\u0078\u0053\u0069\u007A\u0065 = 12;            }            \u0076\u0061\u0072 f\u0072\u006F\u006E\u0074 = \u0047\u0061\u006D\u0065\u004D\u0061\u006E\u0061\u0067\u0065\u0072.\u0073\u0065\u0072\u0076\u0065\u0072.\u0043\u0072\u0065\u0061\u0074\u0065\u0045\u006E\u0074\u0069\u0074\u0079(\u0070\u0072\u0065f\u0061\u0062\u0045\u006E\u0074\u0069\u0074\u0079, \u0047\u0065\u0074\u0052\u0061\u006E\u0064\u006F\u006D\u0050\u006F\u0073\u0069\u0074\u0069\u006F\u006E())?.\u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074>();            \u0069f (f\u0072\u006F\u006E\u0074 == \u006E\u0075\u006C\u006C)            {                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0055\u006E\u0069\u0074\u0079\u0045\u006E\u0067\u0069\u006E\u0065.\u004F\u0062\u006A\u0065\u0063\u0074.\u0044\u0065\u0073\u0074\u0072\u006F\u0079(f\u0072\u006F\u006E\u0074.\u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0044\u0065\u0073\u0074\u0072\u006F\u0079\u004F\u006E\u0047\u0072\u006F\u0075\u006E\u0064\u004D\u0069\u0073\u0073\u0069\u006E\u0067>());            \u0055\u006E\u0069\u0074\u0079\u0045\u006E\u0067\u0069\u006E\u0065.\u004F\u0062\u006A\u0065\u0063\u0074.\u0044\u0065\u0073\u0074\u0072\u006F\u0079(f\u0072\u006F\u006E\u0074.\u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0047\u0072\u006F\u0075\u006E\u0064\u0057\u0061\u0074\u0063\u0068>());            f\u0072\u006F\u006E\u0074.\u0067\u006C\u006F\u0062\u0061\u006C\u0042\u0072\u006F\u0061\u0064\u0063\u0061\u0073\u0074 = \u0074\u0072\u0075\u0065;            f\u0072\u006F\u006E\u0074.\u006E\u0061\u006D\u0065 = \u006B\u0065\u0079\u004E\u0061\u006D\u0065;            f\u0072\u006F\u006E\u0074.\u0065\u006E\u0061\u0062\u006C\u0065\u0053\u0061\u0076\u0069\u006E\u0067 = f\u0061\u006C\u0073\u0065;            f\u0072\u006F\u006E\u0074.\u0053\u0070\u0061\u0077\u006E();                \u0074\u0069\u006D\u0065\u0072.\u004F\u006E\u0063\u0065(1f, () =>            {                \u0069f (\u0070\u006C\u0061\u0079\u0065\u00721.\u0049\u0073\u0056\u0061\u006C\u0069\u0064() == f\u0061\u006C\u0073\u0065 || \u0070\u006C\u0061\u0079\u0065\u00722.\u0049\u0073\u0056\u0061\u006C\u0069\u0064() == f\u0061\u006C\u0073\u0065)                {                    \u0072\u0065\u0074\u0075\u0072\u006E;                }                \u0053\u0065\u006E\u0064\u0045\u006E\u0074\u0069\u0074\u0079(\u0070\u006C\u0061\u0079\u0065\u00721, \u0070\u006C\u0061\u0079\u0065\u00722);                \u0053\u0065\u006E\u0064\u0045\u006E\u0074\u0069\u0074\u0079(\u0070\u006C\u0061\u0079\u0065\u00722, \u0070\u006C\u0061\u0079\u0065\u00721);                \u0076\u0061\u0072 \u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079 = f\u0072\u006F\u006E\u0074.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079;                \u0076\u0061\u0072 \u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079 = f\u0072\u006F\u006E\u0074.\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079;                \u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u0063\u0061\u0070\u0061\u0063\u0069\u0074\u0079 = \u006D\u0061\u0078\u0053\u0069\u007A\u0065;                \u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u0063\u0061\u0070\u0061\u0063\u0069\u0074\u0079 = \u006D\u0061\u0078\u0053\u0069\u007A\u0065;                \u004F\u0070\u0065\u006E\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0070\u006C\u0061\u0079\u0065\u00721, f\u0072\u006F\u006E\u0074, \u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079);                \u004F\u0070\u0065\u006E\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0070\u006C\u0061\u0079\u0065\u00722, f\u0072\u006F\u006E\u0074, \u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079);                f\u0072\u006F\u006E\u0074.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072 = \u0070\u006C\u0061\u0079\u0065\u00721;                \u0070\u006C\u0061\u0079\u0065\u00721.\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u006C\u006F\u006F\u0074.\u0041\u0064\u0064\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079);                \u0070\u006C\u0061\u0079\u0065\u00721.\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u006C\u006F\u006F\u0074.\u0053\u0065\u006E\u0064\u0049\u006D\u006D\u0065\u0064\u0069\u0061\u0074\u0065();                f\u0072\u006F\u006E\u0074.\u0076\u0065\u006E\u0064\u006F\u0072\u0050\u006C\u0061\u0079\u0065\u0072 = \u0070\u006C\u0061\u0079\u0065\u00722;                \u0070\u006C\u0061\u0079\u0065\u00722.\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u006C\u006F\u006F\u0074.\u0041\u0064\u0064\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079);                \u0070\u006C\u0061\u0079\u0065\u00722.\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u006C\u006F\u006F\u0074.\u0053\u0065\u006E\u0064\u0049\u006D\u006D\u0065\u0064\u0069\u0061\u0074\u0065();                f\u0072\u006F\u006E\u0074.\u0055\u0070\u0064\u0061\u0074\u0065\u0050\u006C\u0061\u0079\u0065\u0072\u0073();                \u004D\u006F\u0064\u0069f\u0079\u0046\u0072\u006F\u006E\u0074(f\u0072\u006F\u006E\u0074);                \u004D\u0069\u006D\u0069\u0063\u0050\u006C\u0061\u0079\u0065\u0072(f\u0072\u006F\u006E\u0074, \u0070\u006C\u0061\u0079\u0065\u00722.\u0075\u0073\u0065\u0072\u0049\u0044.\u0049\u0073\u0053\u0074\u0065\u0061\u006D\u0049\u0064() ? \u0070\u006C\u0061\u0079\u0065\u00721 : \u0070\u006C\u0061\u0079\u0065\u00722);                                \u0069f (\u0063\u006F\u006Ef\u0069\u0067.\u0073\u0074\u0061\u0072\u0074\u0043\u006F\u006F\u006C\u0064\u006F\u0077\u006E\u0041\u0074\u0041\u0063\u0063\u0065\u0070\u0074\u0069\u006E\u0067 == \u0074\u0072\u0075\u0065)                {                    \u0076\u0061\u0072 \u0064\u0061\u0074\u00611 = \u0044\u0061\u0074\u0061.\u0047\u0065\u0074(\u0070\u006C\u0061\u0079\u0065\u00721.\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067, \u0074\u0072\u0075\u0065);                    \u0076\u0061\u0072 \u0064\u0061\u0074\u00612 = \u0044\u0061\u0074\u0061.\u0047\u0065\u0074(\u0070\u006C\u0061\u0079\u0065\u00722.\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067, \u0074\u0072\u0075\u0065);                    \u0064\u0061\u0074\u00611.\u006C\u0061\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0055\u0073\u0065 = \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077;                    \u0064\u0061\u0074\u00612.\u006C\u0061\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0055\u0073\u0065 = \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077;                }            });        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0056\u0065\u0063\u0074\u006F\u00723 \u0047\u0065\u0074\u0052\u0061\u006E\u0064\u006F\u006D\u0050\u006F\u0073\u0069\u0074\u0069\u006F\u006E()        {            \u0076\u0061\u0072 \u0072\u0061\u006E\u0064\u006F\u006D\u0058 = \u0043\u006F\u0072\u0065.\u0052\u0061\u006E\u0064\u006F\u006D.\u0052\u0061\u006E\u0067\u0065(-1000, 1000);            \u0076\u0061\u0072 \u0072\u0061\u006E\u0064\u006F\u006D\u005A = \u0043\u006F\u0072\u0065.\u0052\u0061\u006E\u0064\u006F\u006D.\u0052\u0061\u006E\u0067\u0065(-1000, 1000);            \u0076\u0061\u0072 \u0072\u0061\u006E\u0064\u006F\u006D\u0050\u006F\u0073 = \u006E\u0065\u0077 \u0056\u0065\u0063\u0074\u006F\u00723(\u0072\u0061\u006E\u0064\u006F\u006D\u0058, -1000, \u0072\u0061\u006E\u0064\u006F\u006D\u005A);            \u0072\u0065\u0074\u0075\u0072\u006E \u0072\u0061\u006E\u0064\u006F\u006D\u0050\u006F\u0073;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0076\u006F\u0069\u0064 \u004D\u006F\u0064\u0069f\u0079\u0046\u0072\u006F\u006E\u0074(\u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074 f\u0072\u006F\u006E\u0074)        {            f\u0072\u006F\u006E\u0074.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u004D\u0061\u0072\u006B\u0044\u0069\u0072\u0074\u0079();            f\u0072\u006F\u006E\u0074.\u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u004D\u0061\u0072\u006B\u0044\u0069\u0072\u0074\u0079();            f\u0072\u006F\u006E\u0074.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u006F\u006E\u0049\u0074\u0065\u006D\u0041\u0064\u0064\u0065\u0064\u0052\u0065\u006D\u006F\u0076\u0065\u0064 += (\u0069\u0074\u0065\u006D, \u0062) => \u0055\u0070\u0064\u0061\u0074\u0065\u0049\u0074\u0065\u006D(\u0069\u0074\u0065\u006D, \u0062);            f\u0072\u006F\u006E\u0074.\u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u006F\u006E\u0049\u0074\u0065\u006D\u0041\u0064\u0064\u0065\u0064\u0052\u0065\u006D\u006F\u0076\u0065\u0064  += (\u0069\u0074\u0065\u006D, \u0062) => \u0055\u0070\u0064\u0061\u0074\u0065\u0049\u0074\u0065\u006D(\u0069\u0074\u0065\u006D, \u0062);            f\u0072\u006F\u006E\u0074.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u0063\u0061\u006E\u0041\u0063\u0063\u0065\u0070\u0074\u0049\u0074\u0065\u006D += (\u0069\u0074\u0065\u006D, \u0069) =>            {                \u0072\u0065\u0074\u0075\u0072\u006E \u0043\u0061\u006E\u0041\u0063\u0063\u0065\u0070\u0074\u0049\u0074\u0065\u006D(\u0069\u0074\u0065\u006D, \u0069, f\u0072\u006F\u006E\u0074, f\u0061\u006C\u0073\u0065);            };            f\u0072\u006F\u006E\u0074.\u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u0063\u0061\u006E\u0041\u0063\u0063\u0065\u0070\u0074\u0049\u0074\u0065\u006D += (\u0069\u0074\u0065\u006D, \u0069) =>            {                \u0072\u0065\u0074\u0075\u0072\u006E \u0043\u0061\u006E\u0041\u0063\u0063\u0065\u0070\u0074\u0049\u0074\u0065\u006D(\u0069\u0074\u0065\u006D, \u0069, f\u0072\u006F\u006E\u0074, \u0074\u0072\u0075\u0065);            };        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0062\u006F\u006F\u006C \u0043\u0061\u006E\u0041\u0063\u0063\u0065\u0070\u0074\u0049\u0074\u0065\u006D(\u0049\u0074\u0065\u006D \u0069\u0074\u0065\u006D, \u0069\u006E\u0074 \u0073\u006C\u006F\u0074, \u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074 \u0065\u006E\u0074\u0069\u0074\u0079, \u0062\u006F\u006F\u006C f\u006F\u0072\u0056\u0065\u006E\u0064\u006F\u0072)        {            \u0076\u0061\u0072 \u0069\u0074\u0065\u006D\u004F\u0077\u006E\u0065\u0072 = \u0069\u0074\u0065\u006D.\u0047\u0065\u0074\u004F\u0077\u006E\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072();            \u0076\u0061\u0072 \u0069\u0074\u0065\u006D\u0050\u0061\u0072\u0065\u006E\u0074 = \u0069\u0074\u0065\u006D.\u0070\u0061\u0072\u0065\u006E\u0074;            \u0076\u0061\u0072 \u0077\u006F\u0072\u0064 = f\u006F\u0072\u0056\u0065\u006E\u0064\u006F\u0072 ? "\u0056\u0065\u006E\u0064\u006F\u0072" : "\u0043\u0075\u0073\u0074\u006F\u006D\u0065\u0072";            \u0076\u0061\u0072 \u0061\u006C\u006C\u006F\u0077\u0065\u0064\u0050\u006C\u0061\u0079\u0065\u0072 = f\u006F\u0072\u0056\u0065\u006E\u0064\u006F\u0072 ? \u0065\u006E\u0074\u0069\u0074\u0079.\u0076\u0065\u006E\u0064\u006F\u0072\u0050\u006C\u0061\u0079\u0065\u0072 : \u0065\u006E\u0074\u0069\u0074\u0079.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072;            \u0076\u0061\u0072 \u0061\u006C\u006C\u006F\u0077\u0065\u0064\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079 = f\u006F\u0072\u0056\u0065\u006E\u0064\u006F\u0072 ? \u0065\u006E\u0074\u0069\u0074\u0079.\u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079 : \u0065\u006E\u0074\u0069\u0074\u0079.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079;            \u0076\u0061\u0072 f\u006C\u0061\u00671 = \u0061\u006C\u006C\u006F\u0077\u0065\u0064\u0050\u006C\u0061\u0079\u0065\u0072 == \u0069\u0074\u0065\u006D\u004F\u0077\u006E\u0065\u0072;            \u0076\u0061\u0072 f\u006C\u0061\u00672 = \u0069\u0074\u0065\u006D\u0050\u0061\u0072\u0065\u006E\u0074 == \u0061\u006C\u006C\u006F\u0077\u0065\u0064\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079;            \u0076\u0061\u0072 f\u006C\u0061\u00673 = \u0061\u006C\u006C\u006F\u0077\u0065\u0064\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u0047\u0065\u0074\u0053\u006C\u006F\u0074(\u0073\u006C\u006F\u0074) == \u006E\u0075\u006C\u006C;            \u0076\u0061\u0072 f\u006C\u0061\u0067\u0046\u0069\u006E\u0061\u006C = (f\u006C\u0061\u00671 || f\u006C\u0061\u00672) && f\u006C\u0061\u00673;                        \u0069f (\u0069\u0074\u0065\u006D\u004F\u0077\u006E\u0065\u0072 != \u006E\u0075\u006C\u006C && \u0069\u0074\u0065\u006D\u004F\u0077\u006E\u0065\u0072.\u0049\u0073\u0041\u0064\u006D\u0069\u006E == \u0074\u0072\u0075\u0065)            {                \u0069\u0074\u0065\u006D\u004F\u0077\u006E\u0065\u0072.\u0043\u006F\u006E\u0073\u006F\u006C\u0065\u004D\u0065\u0073\u0073\u0061\u0067\u0065($"\u0043\u0061\u006E \u0061\u0063\u0063\u0065\u0070\u0074 '{\u0069\u0074\u0065\u006D.\u0069\u006Ef\u006F.\u0073\u0068\u006F\u0072\u0074\u006E\u0061\u006D\u0065} \u0078{\u0069\u0074\u0065\u006D.\u0061\u006D\u006F\u0075\u006E\u0074}' \u0069\u006E {\u0077\u006F\u0072\u0064}: {f\u006C\u0061\u0067\u0046\u0069\u006E\u0061\u006C} ({f\u006C\u0061\u00671}, {f\u006C\u0061\u00672}, {f\u006C\u0061\u00673})");            }                        \u0069f (f\u006C\u0061\u0067\u0046\u0069\u006E\u0061\u006C == \u0074\u0072\u0075\u0065)            {                \u0052\u0065\u006D\u006F\u0076\u0065\u004D\u006F\u0064\u0073(\u0069\u0074\u0065\u006D);                \u0072\u0065\u0074\u0075\u0072\u006E \u0074\u0072\u0075\u0065;            }            \u0065\u006C\u0073\u0065            {                \u0072\u0065\u0074\u0075\u0072\u006E f\u0061\u006C\u0073\u0065;            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u004D\u0069\u006D\u0069\u0063\u0050\u006C\u0061\u0079\u0065\u0072(\u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074 f\u0072\u006F\u006E\u0074, \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072)        {            \u0069f (\u0070\u006C\u0061\u0079\u0065\u0072.\u0075\u0073\u0065\u0072\u0049\u0044.\u0049\u0073\u0053\u0074\u0065\u0061\u006D\u0049\u0064() == \u0074\u0072\u0075\u0065)            {                \u0072\u0065\u0074\u0075\u0072\u006E;            }                        \u0076\u0061\u0072 \u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079 = f\u0072\u006F\u006E\u0074.\u0076\u0065\u006E\u0064\u006F\u0072\u0050\u006C\u0061\u0079\u0065\u0072 == \u0070\u006C\u0061\u0079\u0065\u0072 ? f\u0072\u006F\u006E\u0074.\u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079 : f\u0072\u006F\u006E\u0074.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079;            \u0074\u0069\u006D\u0065\u0072.\u0052\u0065\u0070\u0065\u0061\u0074(5f, 12, () =>            {                \u0069f (f\u0072\u006F\u006E\u0074.\u0049\u0073\u0056\u0061\u006C\u0069\u0064() == \u0074\u0072\u0075\u0065 && \u0070\u006C\u0061\u0079\u0065\u0072.\u0049\u0073\u0056\u0061\u006C\u0069\u0064() == \u0074\u0072\u0075\u0065)                {                    \u0069f (\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u0069\u0074\u0065\u006D\u004C\u0069\u0073\u0074.\u0043\u006F\u0075\u006E\u0074 == 0)                    {                        \u0076\u0061\u0072 \u0069\u0074\u0065\u006D = \u0049\u0074\u0065\u006D\u004D\u0061\u006E\u0061\u0067\u0065\u0072.\u0043\u0072\u0065\u0061\u0074\u0065\u0042\u0079\u004E\u0061\u006D\u0065("\u0072\u0069f\u006C\u0065.\u0061\u006B");                        \u0076\u0061\u0072 \u0073\u0075\u0062 = \u0049\u0074\u0065\u006D\u004D\u0061\u006E\u0061\u0067\u0065\u0072.\u0043\u0072\u0065\u0061\u0074\u0065\u0042\u0079\u004E\u0061\u006D\u0065("\u0077\u0065\u0061\u0070\u006F\u006E.\u006D\u006F\u0064.8\u0078.\u0073\u0063\u006F\u0070\u0065");                        \u0076\u0061\u0072 \u0069\u0074\u0065\u006D2 = \u0049\u0074\u0065\u006D\u004D\u0061\u006E\u0061\u0067\u0065\u0072.\u0043\u0072\u0065\u0061\u0074\u0065\u0042\u0079\u004E\u0061\u006D\u0065("\u0077\u006F\u006F\u0064", 1000);                        \u0073\u0075\u0062.\u004D\u006F\u0076\u0065\u0054\u006F\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0069\u0074\u0065\u006D.\u0063\u006F\u006E\u0074\u0065\u006E\u0074\u0073);                        \u0070\u006C\u0061\u0079\u0065\u0072.\u0047\u0069\u0076\u0065\u0049\u0074\u0065\u006D(\u0069\u0074\u0065\u006D);                        \u0070\u006C\u0061\u0079\u0065\u0072.\u0047\u0069\u0076\u0065\u0049\u0074\u0065\u006D(\u0069\u0074\u0065\u006D2);                        \u0069\u0074\u0065\u006D.\u004D\u006F\u0076\u0065\u0054\u006F\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079);                        \u0069\u0074\u0065\u006D2.\u004D\u006F\u0076\u0065\u0054\u006F\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079);                    }                                            f\u0072\u006F\u006E\u0074.\u0041\u0063\u0063\u0065\u0070\u0074\u0043\u006C\u0069\u0063\u006B\u0065\u0064(\u006E\u0065\u0077 \u0042\u0061\u0073\u0065\u0045\u006E\u0074\u0069\u0074\u0079.\u0052\u0050\u0043\u004D\u0065\u0073\u0073\u0061\u0067\u0065 {\u0070\u006C\u0061\u0079\u0065\u0072 = \u0070\u006C\u0061\u0079\u0065\u0072});                }            });        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0076\u006F\u0069\u0064 \u004F\u0070\u0065\u006E\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072, \u0042\u0061\u0073\u0065\u0045\u006E\u0074\u0069\u0074\u0079 \u0065\u006E\u0074\u0069\u0074\u0079, \u0049\u0074\u0065\u006D\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072 \u0063\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072)        {            \u0070\u006C\u0061\u0079\u0065\u0072.\u0045\u006E\u0064\u004C\u006F\u006F\u0074\u0069\u006E\u0067();            \u0076\u0061\u0072 \u006C\u006F\u006F\u0074 = \u0070\u006C\u0061\u0079\u0065\u0072.\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079.\u006C\u006F\u006F\u0074;            \u0069f (\u0065\u006E\u0074\u0069\u0074\u0079 == \u006E\u0075\u006C\u006C)            {                \u0076\u0061\u0072 \u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E = \u0070\u006C\u0061\u0079\u0065\u0072.\u0074\u0072\u0061\u006E\u0073f\u006F\u0072\u006D.\u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E + \u006E\u0065\u0077 \u0056\u0065\u0063\u0074\u006F\u00723(0, 500, 0);                \u0065\u006E\u0074\u0069\u0074\u0079 = \u0047\u0061\u006D\u0065\u004D\u0061\u006E\u0061\u0067\u0065\u0072.\u0073\u0065\u0072\u0076\u0065\u0072.\u0043\u0072\u0065\u0061\u0074\u0065\u0045\u006E\u0074\u0069\u0074\u0079("\u0061\u0073\u0073\u0065\u0074\u0073/\u0070\u0072\u0065f\u0061\u0062\u0073/\u0076\u0069\u0073\u0075\u0061\u006C\u0069\u007A\u0061\u0074\u0069\u006F\u006E/\u0073\u0070\u0068\u0065\u0072\u0065.\u0070\u0072\u0065f\u0061\u0062", \u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E);                \u0069f (\u0065\u006E\u0074\u0069\u0074\u0079 != \u006E\u0075\u006C\u006C)                {                    \u0065\u006E\u0074\u0069\u0074\u0079.\u0065\u006E\u0061\u0062\u006C\u0065\u0053\u0061\u0076\u0069\u006E\u0067 = f\u0061\u006C\u0073\u0065;                    \u0065\u006E\u0074\u0069\u0074\u0079.\u0053\u0070\u0061\u0077\u006E();                    \u0063\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072.\u0065\u006E\u0074\u0069\u0074\u0079\u004F\u0077\u006E\u0065\u0072 = \u0065\u006E\u0074\u0069\u0074\u0079;                }                \u0065\u006C\u0073\u0065                {                    \u0072\u0065\u0074\u0075\u0072\u006E;                }            }            \u0063\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072.\u0070\u006C\u0061\u0079\u0065\u0072\u004F\u0077\u006E\u0065\u0072 = \u0070\u006C\u0061\u0079\u0065\u0072;            \u006C\u006F\u006F\u0074.\u0043\u006C\u0065\u0061\u0072();            \u006C\u006F\u006F\u0074.\u0050\u006F\u0073\u0069\u0074\u0069\u006F\u006E\u0043\u0068\u0065\u0063\u006B\u0073 = f\u0061\u006C\u0073\u0065;            \u006C\u006F\u006F\u0074.\u0065\u006E\u0074\u0069\u0074\u0079\u0053\u006F\u0075\u0072\u0063\u0065 = \u0065\u006E\u0074\u0069\u0074\u0079;            \u006C\u006F\u006F\u0074.\u0069\u0074\u0065\u006D\u0053\u006F\u0075\u0072\u0063\u0065 = (\u0049\u0074\u0065\u006D) \u006E\u0075\u006C\u006C;            \u006C\u006F\u006F\u0074.\u004D\u0061\u0072\u006B\u0044\u0069\u0072\u0074\u0079();            \u006C\u006F\u006F\u0074.\u0041\u0064\u0064\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0063\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072);            \u006C\u006F\u006F\u0074.\u0053\u0065\u006E\u0064\u0049\u006D\u006D\u0065\u0064\u0069\u0061\u0074\u0065();            \u0070\u006C\u0061\u0079\u0065\u0072.\u0043\u006C\u0069\u0065\u006E\u0074\u0052\u0050\u0043\u0050\u006C\u0061\u0079\u0065\u0072(\u006E\u0075\u006C\u006C, \u0070\u006C\u0061\u0079\u0065\u0072, "\u0052\u0050\u0043_\u004F\u0070\u0065\u006E\u004C\u006F\u006F\u0074\u0050\u0061\u006E\u0065\u006C", "\u0073\u0068\u006F\u0070f\u0072\u006F\u006E\u0074");            \u0070\u006C\u0061\u0079\u0065\u0072.\u0053\u0065\u006E\u0064\u004E\u0065\u0074\u0077\u006F\u0072\u006B\u0055\u0070\u0064\u0061\u0074\u0065\u0049\u006D\u006D\u0065\u0064\u0069\u0061\u0074\u0065();        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0054\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u00721)        {            \u0076\u0061\u0072 \u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E = \u006E\u0065\u0077 \u0056\u0065\u0063\u0074\u006F\u00723(1000, 2000, 1000);            \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00722 = \u0047\u0061\u006D\u0065\u004D\u0061\u006E\u0061\u0067\u0065\u0072.\u0073\u0065\u0072\u0076\u0065\u0072.\u0043\u0072\u0065\u0061\u0074\u0065\u0045\u006E\u0074\u0069\u0074\u0079(\u0070\u0072\u0065f\u0061\u0062\u0054\u0065\u0073\u0074\u0050\u006C\u0061\u0079\u0065\u0072, \u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E).\u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072>();            \u0069f (\u0070\u006C\u0061\u0079\u0065\u00722 != \u006E\u0075\u006C\u006C)            {                \u0070\u006C\u0061\u0079\u0065\u00722.\u0053\u0070\u0061\u0077\u006E();                \u0069f (\u0074\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0046\u006C\u0061\u0067 == \u0074\u0072\u0075\u0065)                {                    \u0042\u0065\u0067\u0069\u006E\u0054\u0072\u0061\u0064\u0065(\u0070\u006C\u0061\u0079\u0065\u00721, \u0070\u006C\u0061\u0079\u0065\u00722);                }                \u0065\u006C\u0073\u0065                {                    \u0042\u0065\u0067\u0069\u006E\u0054\u0072\u0061\u0064\u0065(\u0070\u006C\u0061\u0079\u0065\u00722, \u0070\u006C\u0061\u0079\u0065\u00721);                }                \u0076\u0061\u0072 \u0074\u0079\u0070\u0065 = \u0074\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0046\u006C\u0061\u0067 ? "\u0063\u0075\u0073\u006F\u006D\u0065\u0072" : "\u0076\u0065\u006E\u0064\u006F\u0072";                \u0074\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0046\u006C\u0061\u0067 = !\u0074\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0046\u006C\u0061\u0067;                \u0070\u006C\u0061\u0079\u0065\u00721.\u0043\u0068\u0061\u0074\u004D\u0065\u0073\u0073\u0061\u0067\u0065($"\u0054\u0065\u0073\u0074 \u0074\u0072\u0061\u0064\u0065 f\u006C\u0061\u0067 \u0069\u0073 \u006E\u006F\u0077: {\u0074\u0065\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0046\u006C\u0061\u0067}, \u0079\u006F\u0075 \u0061\u0072\u0065 \u006E\u006F\u0077 {\u0074\u0079\u0070\u0065}");            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0076\u006F\u0069\u0064 \u0052\u0065\u006D\u006F\u0076\u0065\u004D\u006F\u0064\u0073(\u0049\u0074\u0065\u006D \u0069\u0074\u0065\u006D)        {            \u0069f (\u0069\u0074\u0065\u006D == \u006E\u0075\u006C\u006C)            {                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0076\u0061\u0072 \u0070\u0061\u0072\u0065\u006E\u0074 = \u0069\u0074\u0065\u006D.\u0070\u0061\u0072\u0065\u006E\u0074;            \u0069f (\u0070\u0061\u0072\u0065\u006E\u0074 != \u006E\u0075\u006C\u006C && \u0069\u0074\u0065\u006D.\u0063\u006F\u006E\u0074\u0065\u006E\u0074\u0073 != \u006E\u0075\u006C\u006C)            {                f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u006D\u006F\u0064 \u0069\u006E \u0069\u0074\u0065\u006D.\u0063\u006F\u006E\u0074\u0065\u006E\u0074\u0073.\u0069\u0074\u0065\u006D\u004C\u0069\u0073\u0074.\u0054\u006F\u0041\u0072\u0072\u0061\u0079())                {                    \u0069f (\u006D\u006F\u0064.\u004D\u006F\u0076\u0065\u0054\u006F\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0065\u0072(\u0070\u0061\u0072\u0065\u006E\u0074) == f\u0061\u006C\u0073\u0065)                    {                        \u006D\u006F\u0064.\u0044\u0072\u006F\u0070(\u0069\u0074\u0065\u006D.\u0070\u0061\u0072\u0065\u006E\u0074.\u0064\u0072\u006F\u0070\u0050\u006F\u0073\u0069\u0074\u0069\u006F\u006E, \u0056\u0065\u0063\u0074\u006F\u00723.\u007A\u0065\u0072\u006F);                    }                }            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0076\u006F\u0069\u0064 \u0052\u0065\u0073\u0065\u0074\u0046\u0072\u006F\u006E\u0074(\u0049\u0074\u0065\u006D \u0069\u0074\u0065\u006D)        {            \u0076\u0061\u0072 \u0070\u0061\u0072\u0065\u006E\u0074 = \u0069\u0074\u0065\u006D.\u0070\u0061\u0072\u0065\u006E\u0074?.\u0065\u006E\u0074\u0069\u0074\u0079\u004F\u0077\u006E\u0065\u0072 \u0061\u0073 \u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074;            \u0069f (\u0070\u0061\u0072\u0065\u006E\u0074 != \u006E\u0075\u006C\u006C)            {                \u0070\u0061\u0072\u0065\u006E\u0074.\u0052\u0065\u0073\u0065\u0074\u0054\u0072\u0061\u0064\u0065();            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0076\u006F\u0069\u0064 \u0055\u0070\u0064\u0061\u0074\u0065\u0049\u0074\u0065\u006D(\u0049\u0074\u0065\u006D \u0069\u0074\u0065\u006D, \u0062\u006F\u006F\u006C \u0061\u0063\u0074\u0069\u006F\u006E)        {            \u0069f (\u0061\u0063\u0074\u0069\u006F\u006E)            {                \u0069\u0074\u0065\u006D.\u004F\u006E\u0044\u0069\u0072\u0074\u0079 += \u0052\u0065\u0073\u0065\u0074\u0046\u0072\u006F\u006E\u0074;            }            \u0065\u006C\u0073\u0065            {                \u0069\u0074\u0065\u006D.\u004F\u006E\u0044\u0069\u0072\u0074\u0079 -= \u0052\u0065\u0073\u0065\u0074\u0046\u0072\u006F\u006E\u0074;            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u006F\u0062\u006A\u0065\u0063\u0074 \u0046\u0069\u006E\u0064\u0050\u006C\u0061\u0079\u0065\u0072(\u0073\u0074\u0072\u0069\u006E\u0067 \u0074\u0061\u0072\u0067\u0065\u0074\u004E\u0061\u006D\u0065)        {            \u0076\u0061\u0072 \u006D\u0061\u0074\u0063\u0068 = \u006E\u0065\u0077 \u0050\u0072\u0065\u0064\u0069\u0063\u0061\u0074\u0065<\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072>(\u0078 =>                \u0078.\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067 == \u0074\u0061\u0072\u0067\u0065\u0074\u004E\u0061\u006D\u0065 || \u0078.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065.\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0073(\u0074\u0061\u0072\u0067\u0065\u0074\u004E\u0061\u006D\u0065, \u0043\u006F\u006D\u0070\u0061\u0072\u0065\u004F\u0070\u0074\u0069\u006F\u006E\u0073.\u0049\u0067\u006E\u006F\u0072\u0065\u0043\u0061\u0073\u0065));            \u0076\u0061\u0072 \u0074\u0061\u0072\u0067\u0065\u0074\u0073 = \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072.\u0061\u0063\u0074\u0069\u0076\u0065\u0050\u006C\u0061\u0079\u0065\u0072\u004C\u0069\u0073\u0074.\u0057\u0068\u0065\u0072\u0065(\u0078 => \u006D\u0061\u0074\u0063\u0068(\u0078)).\u0054\u006F\u0041\u0072\u0072\u0061\u0079();            \u0069f (\u0074\u0061\u0072\u0067\u0065\u0074\u0073.\u004C\u0065\u006E\u0067\u0074\u0068 == 0)            {                \u0072\u0065\u0074\u0075\u0072\u006E \u0074\u0061\u0072\u0067\u0065\u0074\u004E\u0061\u006D\u0065;            }            \u0069f (\u0074\u0061\u0072\u0067\u0065\u0074\u0073.\u004C\u0065\u006E\u0067\u0074\u0068 > 1)            {                \u0072\u0065\u0074\u0075\u0072\u006E \u0074\u0061\u0072\u0067\u0065\u0074\u0073.\u0053\u0065\u006C\u0065\u0063\u0074(\u0078 => \u0078.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065).\u0054\u006F\u0053\u0065\u006E\u0074\u0065\u006E\u0063\u0065();            }            \u0072\u0065\u0074\u0075\u0072\u006E \u0074\u0061\u0072\u0067\u0065\u0074\u0073[0];        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0076\u006F\u0069\u0064 \u0052\u0075\u006E\u0045ff\u0065\u0063\u0074(\u0056\u0065\u0063\u0074\u006F\u00723 \u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E, \u0073\u0074\u0072\u0069\u006E\u0067 \u0070\u0072\u0065f\u0061\u0062, \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072 = \u006E\u0075\u006C\u006C)        {            \u0076\u0061\u0072 \u0065ff\u0065\u0063\u0074 = \u006E\u0065\u0077 \u0045ff\u0065\u0063\u0074();                        \u0065ff\u0065\u0063\u0074.\u0049\u006E\u0069\u0074(\u0045ff\u0065\u0063\u0074.\u0054\u0079\u0070\u0065.\u0047\u0065\u006E\u0065\u0072\u0069\u0063, \u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E, \u0056\u0065\u0063\u0074\u006F\u00723.\u007A\u0065\u0072\u006F);            \u0065ff\u0065\u0063\u0074.\u0070\u006F\u006F\u006C\u0065\u0064\u0053\u0074\u0072\u0069\u006E\u0067 = \u0070\u0072\u0065f\u0061\u0062;            \u0076\u0061\u0072 \u0072\u0065\u0070\u0065\u0061\u0074\u0073 = \u0043\u006F\u006E\u0076\u0065\u0072\u0074.\u0054\u006F\u0049\u006E\u007432(\u0063\u006F\u006Ef\u0069\u0067.\u0065ff\u0065\u0063\u0074\u0073\u0056\u006F\u006C\u0075\u006D\u0065);            \u0069f (\u0072\u0065\u0070\u0065\u0061\u0074\u0073 < 1)            {                \u0072\u0065\u0070\u0065\u0061\u0074\u0073 = 1;                \u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E -= \u006E\u0065\u0077 \u0056\u0065\u0063\u0074\u006F\u00723(0, \u004D\u0061\u0074\u0068.\u0041\u0062\u0073(\u0063\u006F\u006Ef\u0069\u0067.\u0065ff\u0065\u0063\u0074\u0073\u0056\u006F\u006C\u0075\u006D\u0065), 0);            }            f\u006F\u0072 (\u0076\u0061\u0072 \u0069 = 0; \u0069 < \u0072\u0065\u0070\u0065\u0061\u0074\u0073; \u0069++)            {                \u0069f (\u0070\u006C\u0061\u0079\u0065\u0072 != \u006E\u0075\u006C\u006C)                {                    \u0045ff\u0065\u0063\u0074\u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u0053\u0065\u006E\u0064(\u0065ff\u0065\u0063\u0074, \u0070\u006C\u0061\u0079\u0065\u0072.\u006E\u0065\u0074.\u0063\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E);                }                \u0065\u006C\u0073\u0065                {                    \u0045ff\u0065\u0063\u0074\u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u0053\u0065\u006E\u0064(\u0065ff\u0065\u0063\u0074);                }            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0076\u006F\u0069\u0064 \u0053\u0065\u006E\u0064\u0045\u006E\u0074\u0069\u0074\u0079(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072, \u0042\u0061\u0073\u0065\u0045\u006E\u0074\u0069\u0074\u0079 \u0065\u006E\u0074\u0069\u0074\u0079)        {            \u0076\u0061\u0072 \u0063\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E = \u0070\u006C\u0061\u0079\u0065\u0072.\u0043\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E;            \u0069f (\u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u004E\u0065\u0074.\u0073\u0076.\u0077\u0072\u0069\u0074\u0065.\u0053\u0074\u0061\u0072\u0074() == f\u0061\u006C\u0073\u0065 || \u0063\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E == \u006E\u0075\u006C\u006C) \u0072\u0065\u0074\u0075\u0072\u006E;            ++\u0063\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E.\u0076\u0061\u006C\u0069\u0064\u0061\u0074\u0065.\u0065\u006E\u0074\u0069\u0074\u0079\u0055\u0070\u0064\u0061\u0074\u0065\u0073;            \u0076\u0061\u0072 \u0073\u0061\u0076\u0065\u0049\u006Ef\u006F = \u006E\u0065\u0077 \u0042\u0061\u0073\u0065\u004E\u0065\u0074\u0077\u006F\u0072\u006B\u0061\u0062\u006C\u0065.\u0053\u0061\u0076\u0065\u0049\u006Ef\u006F() {f\u006F\u0072\u0043\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E = \u0063\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E, f\u006F\u0072\u0044\u0069\u0073\u006B = f\u0061\u006C\u0073\u0065};            \u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u004E\u0065\u0074.\u0073\u0076.\u0077\u0072\u0069\u0074\u0065.\u0050\u0061\u0063\u006B\u0065\u0074\u0049\u0044(\u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u004D\u0065\u0073\u0073\u0061\u0067\u0065.\u0054\u0079\u0070\u0065.\u0045\u006E\u0074\u0069\u0074\u0069\u0065\u0073);            \u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u004E\u0065\u0074.\u0073\u0076.\u0077\u0072\u0069\u0074\u0065.\u0055\u0049\u006E\u007432(\u0063\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E.\u0076\u0061\u006C\u0069\u0064\u0061\u0074\u0065.\u0065\u006E\u0074\u0069\u0074\u0079\u0055\u0070\u0064\u0061\u0074\u0065\u0073);            \u0065\u006E\u0074\u0069\u0074\u0079.\u0054\u006F\u0053\u0074\u0072\u0065\u0061\u006D\u0046\u006F\u0072\u004E\u0065\u0074\u0077\u006F\u0072\u006B((\u0053\u0074\u0072\u0065\u0061\u006D) \u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u004E\u0065\u0074.\u0073\u0076.\u0077\u0072\u0069\u0074\u0065, \u0073\u0061\u0076\u0065\u0049\u006Ef\u006F);            \u004E\u0065\u0074\u0077\u006F\u0072\u006B.\u004E\u0065\u0074.\u0073\u0076.\u0077\u0072\u0069\u0074\u0065.\u0053\u0065\u006E\u0064(\u006E\u0065\u0077 \u0053\u0065\u006E\u0064\u0049\u006Ef\u006F(\u0063\u006F\u006E\u006E\u0065\u0063\u0074\u0069\u006F\u006E));        }                \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u004C\u006F\u0067\u0054\u0072\u0061\u0064\u0065(\u0053\u0068\u006F\u0070\u0046\u0072\u006F\u006E\u0074 \u0065\u006E\u0074\u0069\u0074\u0079)        {            \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00721 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0076\u0065\u006E\u0064\u006F\u0072\u0050\u006C\u0061\u0079\u0065\u0072;            \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u00722 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072;            \u0076\u0061\u0072 \u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u00791 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0076\u0065\u006E\u0064\u006F\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079;            \u0076\u0061\u0072 \u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u00792 = \u0065\u006E\u0074\u0069\u0074\u0079.\u0063\u0075\u0073\u0074\u006F\u006D\u0065\u0072\u0049\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u0079;            \u0076\u0061\u0072 \u0074\u0065\u0078\u0074 = $"\n{\u0070\u006C\u0061\u0079\u0065\u00721.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065}[{\u0070\u006C\u0061\u0079\u0065\u00721.\u0075\u0073\u0065\u0072\u0049\u0044}] (\u0056\u0065\u006E\u0064\u006F\u0072) \u0061\u006E\u0064 {\u0070\u006C\u0061\u0079\u0065\u00722.\u0064\u0069\u0073\u0070\u006C\u0061\u0079\u004E\u0061\u006D\u0065}[{\u0070\u006C\u0061\u0079\u0065\u00722.\u0075\u0073\u0065\u0072\u0049\u0044}] (\u0043\u0075\u0073\u0074\u006F\u006D\u0065\u0072)\n" +                       $"\u0046\u0069\u006E\u0069\u0073\u0068\u0065\u0064 \u0074\u0072\u0061\u0064\u0065 \u0061\u0074 {\u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077} (\u0055\u0054\u0043) \u0077\u0069\u0074\u0068 {\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u00791.\u0069\u0074\u0065\u006D\u004C\u0069\u0073\u0074.\u0043\u006F\u0075\u006E\u0074} + {\u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u00792.\u0069\u0074\u0065\u006D\u004C\u0069\u0073\u0074.\u0043\u006F\u0075\u006E\u0074} \u0069\u0074\u0065\u006D\u0073!\n";             \u0074\u0065\u0078\u0074 += "\u0056\u0065\u006E\u0064\u006F\u0072 \u0073\u0065\u006E\u0074:\n";            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0069\u0074\u0065\u006D \u0069\u006E \u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u00791.\u0069\u0074\u0065\u006D\u004C\u0069\u0073\u0074)            {                \u0074\u0065\u0078\u0074 += $" * {\u0069\u0074\u0065\u006D.\u0069\u006Ef\u006F.\u0073\u0068\u006F\u0072\u0074\u006E\u0061\u006D\u0065} \u0078{\u0069\u0074\u0065\u006D.\u0061\u006D\u006F\u0075\u006E\u0074}\n";            }                        \u0074\u0065\u0078\u0074 += "\u0043\u0075\u0073\u0074\u006F\u006D\u0065\u0072 \u0073\u0065\u006E\u0074:\n";            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0069\u0074\u0065\u006D \u0069\u006E \u0069\u006E\u0076\u0065\u006E\u0074\u006F\u0072\u00792.\u0069\u0074\u0065\u006D\u004C\u0069\u0073\u0074)            {                \u0074\u0065\u0078\u0074 += $" * {\u0069\u0074\u0065\u006D.\u0069\u006Ef\u006F.\u0073\u0068\u006F\u0072\u0074\u006E\u0061\u006D\u0065} \u0078{\u0069\u0074\u0065\u006D.\u0061\u006D\u006F\u0075\u006E\u0074}\n";            }                        \u004C\u006F\u0067\u0054\u006F\u0046\u0069\u006C\u0065("\u0072\u0065\u0073\u0075\u006C\u0074\u0073", \u0074\u0065\u0078\u0074, \u0074\u0068\u0069\u0073);        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0043\u006F\u006Ef\u0069\u0067\u0044\u0061\u0074\u0061 \u0063\u006F\u006Ef\u0069\u0067 = \u006E\u0065\u0077 \u0043\u006F\u006Ef\u0069\u0067\u0044\u0061\u0074\u0061();        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006C\u0061\u0073\u0073 \u0043\u006F\u006Ef\u0069\u0067\u0044\u0061\u0074\u0061        {            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0043\u006F\u006D\u006D\u0061\u006E\u0064")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067[] \u0063\u006F\u006D\u006D\u0061\u006E\u0064 =            {                "\u0074\u0072\u0061\u0064\u0065",                "\u0074"            };            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0045\u0078\u0074\u0072\u0061 \u0061\u0063\u0063\u0065\u0070\u0074 \u0063\u006F\u006D\u006D\u0061\u006E\u0064")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067[] \u0061\u0063\u0063\u0065\u0070\u0074\u0043\u006F\u006D\u006D\u0061\u006E\u0064 =            {                "\u0074\u0061",                "\u0074\u0061\u0063\u0063\u0065\u0070\u0074"            };            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0045\u0078\u0074\u0072\u0061 \u0064\u0065\u0063\u006C\u0069\u006E\u0065 \u0063\u006F\u006D\u006D\u0061\u006E\u0064")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067[] \u0064\u0065\u0063\u006C\u0069\u006E\u0065\u0043\u006F\u006D\u006D\u0061\u006E\u0064 =            {                "\u0074\u0064",                "\u0074\u0063\u0061\u006E\u0063\u0065\u006C",            };            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0045ff\u0065\u0063\u0074 \u006F\u006E \u0063\u006F\u006D\u0070\u006C\u0065\u0074\u0069\u006E\u0067 \u0074\u0072\u0061\u0064\u0065")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067 \u0065ff\u0065\u0063\u0074\u004F\u006E\u0043\u006F\u006D\u0070\u006C\u0065\u0074\u0065\u0054\u0072\u0061\u0064\u0065 = "\u0061\u0073\u0073\u0065\u0074\u0073/\u0070\u0072\u0065f\u0061\u0062\u0073/\u0062\u0075\u0069\u006C\u0064\u0069\u006E\u0067/\u0077\u0061\u006C\u006C.f\u0072\u0061\u006D\u0065.\u0073\u0068\u006F\u0070f\u0072\u006F\u006E\u0074/\u0065ff\u0065\u0063\u0074\u0073/\u006D\u0065\u0074\u0061\u006C_\u0074\u0072\u0061\u006E\u0073\u0061\u0063\u0074\u0069\u006F\u006E_\u0063\u006F\u006D\u0070\u006C\u0065\u0074\u0065.\u0070\u0072\u0065f\u0061\u0062";            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0045ff\u0065\u0063\u0074 \u006F\u006E \u0070\u0065\u006E\u0064\u0069\u006E\u0067 \u0072\u0065\u0071\u0075\u0065\u0073\u0074")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067 \u0065ff\u0065\u0063\u0074\u004F\u006E\u0052\u0065\u0071\u0075\u0065\u0073\u0074 = "\u0061\u0073\u0073\u0065\u0074\u0073/\u0062\u0075\u006E\u0064\u006C\u0065\u0064/\u0070\u0072\u0065f\u0061\u0062\u0073/f\u0078/\u0069\u006E\u0076\u0069\u0074\u0065_\u006E\u006F\u0074\u0069\u0063\u0065.\u0070\u0072\u0065f\u0061\u0062";            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u004C\u006F\u0067 \u0074\u0072\u0061\u0064\u0065\u0073")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0062\u006F\u006F\u006C \u006C\u006F\u0067\u0054\u0072\u0061\u0064\u0065 = f\u0061\u006C\u0073\u0065;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0042\u006C\u006F\u0063\u006B \u0074\u0072\u0061\u0064\u0065 \u0069\u006E \u0072\u0061\u0069\u0064\u0062\u006C\u006F\u0063\u006B")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0062\u006F\u006F\u006C \u0062\u006C\u006F\u0063\u006B\u0049\u006E\u0052\u0061\u0069\u0064\u0062\u006C\u006F\u0063\u006B = \u0074\u0072\u0075\u0065;             [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0042\u006C\u006F\u0063\u006B \u0069\u006E \u0062\u0075\u0069\u006C\u0064\u0069\u006E\u0067 \u0070\u0072\u0069\u0076\u0069\u006C\u0065\u0067\u0065")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0062\u006F\u006F\u006C \u0062\u006C\u006F\u0063\u006B\u0049\u006E\u0042\u0075\u0069\u006C\u0064\u0069\u006E\u0067\u0050\u0072\u0069\u0076\u0069\u006C\u0065\u0067\u0065 = \u0074\u0072\u0075\u0065;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0053\u0074\u0061\u0072\u0074 \u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E \u0061f\u0074\u0065\u0072 \u0061\u0063\u0063\u0065\u0070\u0074\u0069\u006E\u0067 \u0074\u0072\u0061\u0064\u0065")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0062\u006F\u006F\u006C \u0073\u0074\u0061\u0072\u0074\u0043\u006F\u006F\u006C\u0064\u006F\u0077\u006E\u0041\u0074\u0041\u0063\u0063\u0065\u0070\u0074\u0069\u006E\u0067 = f\u0061\u006C\u0073\u0065;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0045ff\u0065\u0063\u0074\u0073 \u0076\u006F\u006C\u0075\u006D\u0065")]            \u0070\u0075\u0062\u006C\u0069\u0063 f\u006C\u006F\u0061\u0074 \u0065ff\u0065\u0063\u0074\u0073\u0056\u006F\u006C\u0075\u006D\u0065 = 1f;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079[] \u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073 =            {                \u006E\u0065\u0077 \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079 {\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E = "\u0074\u0072\u0061\u0064\u0065.\u0064\u0065f\u0061\u0075\u006C\u0074", \u0070\u0072\u0069\u006F\u0072\u0069\u0074\u0079 = 1, \u0073\u0069\u007A\u0065 = 2, \u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E = 600,},                \u006E\u0065\u0077 \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079 {\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E = "\u0074\u0072\u0061\u0064\u0065.\u0076\u0069\u0070", \u0070\u0072\u0069\u006F\u0072\u0069\u0074\u0079 = 2, \u0073\u0069\u007A\u0065 = 6, \u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E = 300,},                \u006E\u0065\u0077 \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079 {\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E = "\u0074\u0072\u0061\u0064\u0065.\u0074\u006F\u0070", \u0070\u0072\u0069\u006F\u0072\u0069\u0074\u0079 = 3, \u0073\u0069\u007A\u0065 = 12, \u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E = 60,},            };        }        \u0070\u0072\u006F\u0074\u0065\u0063\u0074\u0065\u0064 \u006F\u0076\u0065\u0072\u0072\u0069\u0064\u0065 \u0076\u006F\u0069\u0064 \u004C\u006F\u0061\u0064\u0043\u006F\u006Ef\u0069\u0067()        {            \u0062\u0061\u0073\u0065.\u004C\u006F\u0061\u0064\u0043\u006F\u006Ef\u0069\u0067();            \u0074\u0072\u0079            {                \u0063\u006F\u006Ef\u0069\u0067 = \u0043\u006F\u006Ef\u0069\u0067.\u0052\u0065\u0061\u0064\u004F\u0062\u006A\u0065\u0063\u0074<\u0043\u006F\u006Ef\u0069\u0067\u0044\u0061\u0074\u0061>();                \u0069f (\u0063\u006F\u006Ef\u0069\u0067 == \u006E\u0075\u006C\u006C)                {                    \u004C\u006F\u0061\u0064\u0044\u0065f\u0061\u0075\u006C\u0074\u0043\u006F\u006Ef\u0069\u0067();                }            }            \u0063\u0061\u0074\u0063\u0068            {                \u0050\u0072\u0069\u006E\u0074\u0045\u0072\u0072\u006F\u0072("\u0043\u006F\u006Ef\u0069\u0067\u0075\u0072\u0061\u0074\u0069\u006F\u006E f\u0069\u006C\u0065 \u0069\u0073 \u0063\u006F\u0072\u0072\u0075\u0070\u0074! \u0043\u0068\u0065\u0063\u006B \u0079\u006F\u0075\u0072 \u0063\u006F\u006Ef\u0069\u0067 f\u0069\u006C\u0065 \u0061\u0074 \u0068\u0074\u0074\u0070\u0073://\u006A\u0073\u006F\u006E\u006C\u0069\u006E\u0074.\u0063\u006F\u006D/");                \u0074\u0069\u006D\u0065\u0072.\u0045\u0076\u0065\u0072\u0079(10f,                    () =>                    {                        \u0050\u0072\u0069\u006E\u0074\u0045\u0072\u0072\u006F\u0072("\u0043\u006F\u006Ef\u0069\u0067\u0075\u0072\u0061\u0074\u0069\u006F\u006E f\u0069\u006C\u0065 \u0069\u0073 \u0063\u006F\u0072\u0072\u0075\u0070\u0074! \u0043\u0068\u0065\u0063\u006B \u0079\u006F\u0075\u0072 \u0063\u006F\u006Ef\u0069\u0067 f\u0069\u006C\u0065 \u0061\u0074 \u0068\u0074\u0074\u0070\u0073://\u006A\u0073\u006F\u006E\u006C\u0069\u006E\u0074.\u0063\u006F\u006D/");                    });                \u004C\u006F\u0061\u0064\u0044\u0065f\u0061\u0075\u006C\u0074\u0043\u006F\u006Ef\u0069\u0067();                \u0072\u0065\u0074\u0075\u0072\u006E;            }            \u0053\u0061\u0076\u0065\u0043\u006F\u006Ef\u0069\u0067();        }        \u0070\u0072\u006F\u0074\u0065\u0063\u0074\u0065\u0064 \u006F\u0076\u0065\u0072\u0072\u0069\u0064\u0065 \u0076\u006F\u0069\u0064 \u004C\u006F\u0061\u0064\u0044\u0065f\u0061\u0075\u006C\u0074\u0043\u006F\u006Ef\u0069\u0067()        {            \u0063\u006F\u006Ef\u0069\u0067 = \u006E\u0065\u0077 \u0043\u006F\u006Ef\u0069\u0067\u0044\u0061\u0074\u0061();        }        \u0070\u0072\u006F\u0074\u0065\u0063\u0074\u0065\u0064 \u006F\u0076\u0065\u0072\u0072\u0069\u0064\u0065 \u0076\u006F\u0069\u0064 \u0053\u0061\u0076\u0065\u0043\u006F\u006Ef\u0069\u0067()        {            \u0043\u006F\u006Ef\u0069\u0067.\u0057\u0072\u0069\u0074\u0065\u004F\u0062\u006A\u0065\u0063\u0074(\u0063\u006F\u006Ef\u0069\u0067);        }                        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u006F\u0062\u006A\u0065\u0063\u0074, \u0073\u0074\u0072\u0069\u006E\u0067> \u006C\u0061\u006E\u0067\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0073 = \u006E\u0065\u0077 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u006F\u0062\u006A\u0065\u0063\u0074, \u0073\u0074\u0072\u0069\u006E\u0067>        {            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0055\u0073\u0061\u0067\u0065, "\u0055\u0073\u0061\u0067\u0065:\n/\u0074\u0072\u0061\u0064\u0065 \u0070\u006C\u0061\u0079\u0065\u0072\u004E\u0061\u006D\u0065\n/\u0074\u0072\u0061\u0064\u0065 \u0079\u0065\u0073\n/\u0074\u0072\u0061\u0064\u0065 \u006E\u006F"},             {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u004E\u006F\u0050\u0065\u006E\u0064\u0069\u006E\u0067, "\u0054\u0068\u0065\u0072\u0065 \u0061\u0072\u0065 \u006E\u006F \u0070\u0065\u006E\u0064\u0069\u006E\u0067 \u0074\u0072\u0061\u0064\u0065\u0073!"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0041\u006C\u0072\u0065\u0061\u0064\u0079\u0050\u0065\u006E\u0064\u0069\u006E\u0067, "\u0054\u0068\u0061\u0074 \u0070\u006C\u0061\u0079\u0065\u0072 \u0061\u006C\u0072\u0065\u0061\u0064\u0079 \u0068\u0061\u0076\u0065 \u0070\u0065\u006E\u0064\u0069\u006E\u0067 \u0072\u0065\u0071\u0075\u0065\u0073\u0074\u0073!"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0054\u0072\u0061\u0064\u0065\u0042\u0065\u0067\u0069\u006E\u0073, "\u0054\u0072\u0061\u0064\u0065 \u0062\u0065\u0074\u0077\u0065\u0065\u006E {\u006E\u0061\u006D\u00651} \u0061\u006E\u0064 {\u006E\u0061\u006D\u00652} \u0062\u0065\u0067\u0069\u006E\u0073!"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0053\u0065\u006E\u0074, "\u0059\u006F\u0075 \u0073\u0065\u006E\u0074 \u0074\u0072\u0061\u0064\u0065 \u0072\u0065\u0071\u0075\u0065\u0073\u0074 \u0074\u006F {\u006E\u0061\u006D\u0065}"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0052\u0065\u0063\u0065\u0069\u0076\u0065\u0064, "\u0059\u006F\u0075 \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0064 \u0074\u0072\u0061\u0064\u0065 \u0072\u0065\u0071\u0075\u0065\u0073\u0074 f\u0072\u006F\u006D {\u006E\u0061\u006D\u0065}"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0054\u0072\u0061\u0064\u0065\u0043\u0061\u006E\u0063\u0065\u006C\u006C\u0065\u0064, "\u0054\u0072\u0061\u0064\u0065 \u0077\u0061\u0073 \u0063\u0061\u006E\u0063\u0065\u006C\u006C\u0065\u0064"},             {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0043\u0061\u006E\u0074\u0052\u0069\u0067\u0068\u0074\u004E\u006F\u0077, "\u0059\u006F\u0075 \u0063\u0061\u006E'\u0074 \u0064\u006F \u0074\u0068\u0061\u0074 \u0072\u0069\u0067\u0068\u0074 \u006E\u006F\u0077"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0043\u006F\u006F\u006C\u0064\u006F\u0077\u006E, "\u0043\u006F\u006F\u006C\u0064\u006F\u0077\u006E f\u006F\u0072 {\u0073\u0065\u0063\u006F\u006E\u0064\u0073}"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E, "\u0059\u006F\u0075 \u0064\u006F\u006E'\u0074 \u0068\u0061\u0076\u0065 \u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E \u0074\u006F \u0064\u006F \u0074\u0068\u0061\u0074!"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u004E\u006F\u0050\u006C\u0061\u0079\u0065\u0072\u0073, "\u0054\u0068\u0065\u0072\u0065 \u0061\u0072\u0065 \u006E\u006F \u0070\u006C\u0061\u0079\u0065\u0072\u0073 \u0077\u0069\u0074\u0068 \u0074\u0068\u0061\u0074 '\u004E\u0061\u006D\u0065' \u006F\u0072 '\u0053\u0074\u0065\u0061\u006D \u0049\u0044' ({\u006E\u0061\u006D\u0065})"},            {\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u004D\u0075\u006C\u0074\u0069\u0070\u006C\u0065\u0050\u006C\u0061\u0079\u0065\u0072\u0073, "\u0054\u0068\u0065\u0072\u0065 \u0061\u0072\u0065 \u006D\u0075\u006C\u0074\u0069\u0070\u006C\u0065 \u0070\u006C\u0061\u0079\u0065\u0072\u0073 \u0077\u0069\u0074\u0068 \u0074\u0068\u0061\u0074 '\u004E\u0061\u006D\u0065' :\n{\u006C\u0069\u0073\u0074}"}        };        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0065\u006E\u0075\u006D \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065        {            \u0055\u0073\u0061\u0067\u0065,            \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E,            \u0043\u006F\u006F\u006C\u0064\u006F\u0077\u006E,            \u004E\u006F\u0050\u0065\u006E\u0064\u0069\u006E\u0067,            \u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0041\u006C\u0072\u0065\u0061\u0064\u0079\u0050\u0065\u006E\u0064\u0069\u006E\u0067,            \u0054\u0072\u0061\u0064\u0065\u0042\u0065\u0067\u0069\u006E\u0073,            \u0054\u0072\u0061\u0064\u0065\u0043\u0061\u006E\u0063\u0065\u006C\u006C\u0065\u0064,            \u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0053\u0065\u006E\u0074,            \u0052\u0065\u0071\u0075\u0065\u0073\u0074\u0052\u0065\u0063\u0065\u0069\u0076\u0065\u0064,            \u0043\u0061\u006E\u0074\u0052\u0069\u0067\u0068\u0074\u004E\u006F\u0077,            \u004D\u0075\u006C\u0074\u0069\u0070\u006C\u0065\u0050\u006C\u0061\u0079\u0065\u0072\u0073,            \u004E\u006F\u0050\u006C\u0061\u0079\u0065\u0072\u0073        }                \u0070\u0072\u006F\u0074\u0065\u0063\u0074\u0065\u0064 \u006F\u0076\u0065\u0072\u0072\u0069\u0064\u0065 \u0076\u006F\u0069\u0064 \u004C\u006F\u0061\u0064\u0044\u0065f\u0061\u0075\u006C\u0074\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0073()        {            \u0076\u0061\u0072 \u0064\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079 = \u006E\u0065\u0077 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u0073\u0074\u0072\u0069\u006E\u0067>();            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0070\u0061\u0069\u0072 \u0069\u006E \u006C\u0061\u006E\u0067\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0073)            {                \u0076\u0061\u0072 \u006B\u0065\u0079 = \u0070\u0061\u0069\u0072.\u004B\u0065\u0079.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();                \u0076\u0061\u0072 \u0076\u0061\u006C\u0075\u0065 = \u0070\u0061\u0069\u0072.\u0056\u0061\u006C\u0075\u0065;                \u0064\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079.\u0054\u0072\u0079\u0041\u0064\u0064(\u006B\u0065\u0079, \u0076\u0061\u006C\u0075\u0065);            }            \u006C\u0061\u006E\u0067.\u0052\u0065\u0067\u0069\u0073\u0074\u0065\u0072\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0073(\u0064\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079, \u0074\u0068\u0069\u0073);        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0072\u0069\u006E\u0067 \u0047\u0065\u0074\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065 \u006B\u0065\u0079, \u0073\u0074\u0072\u0069\u006E\u0067 \u0070\u006C\u0061\u0079\u0065\u0072\u0049\u0044 = \u006E\u0075\u006C\u006C, \u0070\u0061\u0072\u0061\u006D\u0073 \u006F\u0062\u006A\u0065\u0063\u0074[] \u0061\u0072\u0067\u0073)        {            \u0076\u0061\u0072 \u006B\u0065\u0079\u0053\u0074\u0072\u0069\u006E\u0067 = \u006B\u0065\u0079.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();            \u0076\u0061\u0072 \u006D\u0065\u0073\u0073\u0061\u0067\u0065 = \u006C\u0061\u006E\u0067.\u0047\u0065\u0074\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u006B\u0065\u0079\u0053\u0074\u0072\u0069\u006E\u0067, \u0074\u0068\u0069\u0073, \u0070\u006C\u0061\u0079\u0065\u0072\u0049\u0044);            \u0069f (\u006D\u0065\u0073\u0073\u0061\u0067\u0065 == \u006B\u0065\u0079\u0053\u0074\u0072\u0069\u006E\u0067)            {                \u0072\u0065\u0074\u0075\u0072\u006E $"{\u006B\u0065\u0079\u0053\u0074\u0072\u0069\u006E\u0067} \u0069\u0073 \u006E\u006F\u0074 \u0064\u0065f\u0069\u006E\u0065\u0064 \u0069\u006E \u006C\u0061\u006E\u0067!";            }                        \u0076\u0061\u0072 \u006F\u0072\u0067\u0061\u006E\u0069\u007A\u0065\u0064 = \u004F\u0072\u0067\u0061\u006E\u0069\u007A\u0065\u0041\u0072\u0067\u0073(\u0061\u0072\u0067\u0073);            \u006D\u0065\u0073\u0073\u0061\u0067\u0065 = \u0052\u0065\u0070\u006C\u0061\u0063\u0065\u0041\u0072\u0067\u0073(\u006D\u0065\u0073\u0073\u0061\u0067\u0065, \u006F\u0072\u0067\u0061\u006E\u0069\u007A\u0065\u0064);            \u0072\u0065\u0074\u0075\u0072\u006E \u006D\u0065\u0073\u0073\u0061\u0067\u0065;        }                \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u006F\u0062\u006A\u0065\u0063\u0074> \u004F\u0072\u0067\u0061\u006E\u0069\u007A\u0065\u0041\u0072\u0067\u0073(\u006F\u0062\u006A\u0065\u0063\u0074[] \u0061\u0072\u0067\u0073)        {            \u0076\u0061\u0072 \u0064\u0069\u0063 = \u006E\u0065\u0077 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u006F\u0062\u006A\u0065\u0063\u0074>();            f\u006F\u0072 (\u0076\u0061\u0072 \u0069 = 0; \u0069 < \u0061\u0072\u0067\u0073.\u004C\u0065\u006E\u0067\u0074\u0068; \u0069 += 2)            {                \u0076\u0061\u0072 \u0076\u0061\u006C\u0075\u0065 = \u0061\u0072\u0067\u0073[\u0069].\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();                \u0076\u0061\u0072 \u006E\u0065\u0078\u0074\u0056\u0061\u006C\u0075\u0065 = \u0069 + 1 < \u0061\u0072\u0067\u0073.\u004C\u0065\u006E\u0067\u0074\u0068 ? \u0061\u0072\u0067\u0073[\u0069 + 1] : \u006E\u0075\u006C\u006C;                \u0064\u0069\u0063.\u0054\u0072\u0079\u0041\u0064\u0064(\u0076\u0061\u006C\u0075\u0065, \u006E\u0065\u0078\u0074\u0056\u0061\u006C\u0075\u0065);            }            \u0072\u0065\u0074\u0075\u0072\u006E \u0064\u0069\u0063;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067 \u0052\u0065\u0070\u006C\u0061\u0063\u0065\u0041\u0072\u0067\u0073(\u0073\u0074\u0072\u0069\u006E\u0067 \u006D\u0065\u0073\u0073\u0061\u0067\u0065, \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u006F\u0062\u006A\u0065\u0063\u0074> \u0061\u0072\u0067\u0073)        {            \u0069f (\u0061\u0072\u0067\u0073 == \u006E\u0075\u006C\u006C || \u0061\u0072\u0067\u0073.\u0043\u006F\u0075\u006E\u0074 < 1)            {                \u0072\u0065\u0074\u0075\u0072\u006E \u006D\u0065\u0073\u0073\u0061\u0067\u0065;            }                        f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0070\u0061\u0069\u0072 \u0069\u006E \u0061\u0072\u0067\u0073)            {                \u0076\u0061\u0072 \u00730 = "{" + \u0070\u0061\u0069\u0072.\u004B\u0065\u0079 + "}";                \u0076\u0061\u0072 \u00731 = \u0070\u0061\u0069\u0072.\u004B\u0065\u0079;                \u0076\u0061\u0072 \u00732 = \u0070\u0061\u0069\u0072.\u0056\u0061\u006C\u0075\u0065 != \u006E\u0075\u006C\u006C ? \u0070\u0061\u0069\u0072.\u0056\u0061\u006C\u0075\u0065.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067() : "\u006E\u0075\u006C\u006C";                \u006D\u0065\u0073\u0073\u0061\u0067\u0065 = \u006D\u0065\u0073\u0073\u0061\u0067\u0065.\u0052\u0065\u0070\u006C\u0061\u0063\u0065(\u00730, \u00732, \u0053\u0074\u0072\u0069\u006E\u0067\u0043\u006F\u006D\u0070\u0061\u0072\u0069\u0073\u006F\u006E.\u0049\u006E\u0076\u0061\u0072\u0069\u0061\u006E\u0074\u0043\u0075\u006C\u0074\u0075\u0072\u0065\u0049\u0067\u006E\u006F\u0072\u0065\u0043\u0061\u0073\u0065);                \u006D\u0065\u0073\u0073\u0061\u0067\u0065 = \u006D\u0065\u0073\u0073\u0061\u0067\u0065.\u0052\u0065\u0070\u006C\u0061\u0063\u0065(\u00731, \u00732, \u0053\u0074\u0072\u0069\u006E\u0067\u0043\u006F\u006D\u0070\u0061\u0072\u0069\u0073\u006F\u006E.\u0049\u006E\u0076\u0061\u0072\u0069\u0061\u006E\u0074\u0043\u0075\u006C\u0074\u0075\u0072\u0065\u0049\u0067\u006E\u006F\u0072\u0065\u0043\u0061\u0073\u0065);            }            \u0072\u0065\u0074\u0075\u0072\u006E \u006D\u0065\u0073\u0073\u0061\u0067\u0065;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u006F\u0062\u006A\u0065\u0063\u0074 \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065 \u006B\u0065\u0079, \u0070\u0061\u0072\u0061\u006D\u0073 \u006F\u0062\u006A\u0065\u0063\u0074[] \u0061\u0072\u0067\u0073)        {            \u0076\u0061\u0072 \u0075\u0073\u0065\u0072\u0049\u0044 = (\u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072 \u0061\u0073 \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072)?.\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067;            \u0076\u0061\u0072 \u006D\u0065\u0073\u0073\u0061\u0067\u0065 = \u0047\u0065\u0074\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u006B\u0065\u0079, \u0075\u0073\u0065\u0072\u0049\u0044, \u0061\u0072\u0067\u0073);            \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072, \u006D\u0065\u0073\u0073\u0061\u0067\u0065);        }                \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u006F\u0062\u006A\u0065\u0063\u0074 \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072, \u0073\u0074\u0072\u0069\u006E\u0067 \u006D\u0065\u0073\u0073\u0061\u0067\u0065)        {            \u0069f (\u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072 == \u006E\u0075\u006C\u006C)            {                \u0050\u0075\u0074\u0073(\u006D\u0065\u0073\u0073\u0061\u0067\u0065);                \u0072\u0065\u0074\u0075\u0072\u006E;            }                        \u0076\u0061\u0072 \u0063\u006F\u006E\u0073\u006F\u006C\u0065 = \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072 \u0061\u0073 \u0043\u006F\u006E\u0073\u006F\u006C\u0065\u0053\u0079\u0073\u0074\u0065\u006D.\u0041\u0072\u0067;            \u0069f (\u0063\u006F\u006E\u0073\u006F\u006C\u0065 != \u006E\u0075\u006C\u006C)            {                \u0053\u0065\u006E\u0064\u0052\u0065\u0070\u006C\u0079(\u0063\u006F\u006E\u0073\u006F\u006C\u0065, \u006D\u0065\u0073\u0073\u0061\u0067\u0065);                \u0072\u0065\u0074\u0075\u0072\u006E;            }                        \u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u0072 = \u0072\u0065\u0063\u0065\u0069\u0076\u0065\u0072 \u0061\u0073 \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072;            \u0069f (\u0070\u006C\u0061\u0079\u0065\u0072 != \u006E\u0075\u006C\u006C)            {                \u0070\u006C\u0061\u0079\u0065\u0072.\u0043\u0068\u0061\u0074\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u006D\u0065\u0073\u0073\u0061\u0067\u0065);                \u0072\u0065\u0074\u0075\u0072\u006E;            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0042\u0072\u006F\u0061\u0064\u0063\u0061\u0073\u0074(\u0073\u0074\u0072\u0069\u006E\u0067 \u006D\u0065\u0073\u0073\u0061\u0067\u0065)        {            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0070\u006C\u0061\u0079\u0065\u0072 \u0069\u006E \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072.\u0061\u0063\u0074\u0069\u0076\u0065\u0050\u006C\u0061\u0079\u0065\u0072\u004C\u0069\u0073\u0074)            {                \u0070\u006C\u0061\u0079\u0065\u0072.\u0043\u0068\u0061\u0074\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u006D\u0065\u0073\u0073\u0061\u0067\u0065);            }        }                        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0050\u006C\u0075\u0067\u0069\u006E\u0044\u0061\u0074\u0061 \u0044\u0061\u0074\u0061 = \u006E\u0065\u0077 \u0050\u006C\u0075\u0067\u0069\u006E\u0044\u0061\u0074\u0061();        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0072\u0069\u006E\u0067 \u0064\u0061\u0074\u0061\u0046\u0069\u006C\u0065\u006E\u0061\u006D\u0065 => $"{\u004E\u0061\u006D\u0065}\\\u0064\u0061\u0074\u0061";        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0062\u006F\u006F\u006C \u0064\u0061\u0074\u0061\u0056\u0061\u006C\u0069\u0064 = f\u0061\u006C\u0073\u0065;        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006C\u0061\u0073\u0073 \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079        {            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065 \u006C\u0061\u0073\u0074\u0055\u0073\u0065 = \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0069\u006E\u0074 \u006C\u006F\u0061\u0064\u0073\u0043\u006F\u0075\u006E\u0074 = 0;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0075\u0062\u006C\u0069\u0063 \u0064\u006F\u0075\u0062\u006C\u0065 \u0064\u0061\u0079\u0073\u0053\u0069\u006E\u0063\u0065\u004C\u0061\u0073\u0074\u0055\u0073\u0065 => (\u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077 - \u006C\u0061\u0073\u0074\u0055\u0073\u0065).\u0054\u006F\u0074\u0061\u006C\u0044\u0061\u0079\u0073;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079] \u0070\u0075\u0062\u006C\u0069\u0063 \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065 \u006C\u0061\u0073\u0074\u0054\u0072\u0061\u0064\u0065\u0055\u0073\u0065;            \u0070\u0075\u0062\u006C\u0069\u0063 \u0076\u006F\u0069\u0064 \u004D\u0061\u0072\u006B\u0055\u0073\u0065\u0064()            {                \u006C\u0061\u0073\u0074\u0055\u0073\u0065 = \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065.\u0055\u0074\u0063\u004E\u006F\u0077;                \u006C\u006F\u0061\u0064\u0073\u0043\u006F\u0075\u006E\u0074++;            }        }                \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006C\u0061\u0073\u0073 \u0050\u006C\u0075\u0067\u0069\u006E\u0044\u0061\u0074\u0061        {            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079> \u0076\u0061\u006C\u0075\u0065\u0073 = \u006E\u0065\u0077 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079>();            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079] \u0070\u0075\u0062\u006C\u0069\u0063 \u0072\u0065\u0061\u0064\u006F\u006E\u006C\u0079 \u0044\u0061\u0074\u0065\u0054\u0069\u006D\u0065 \u0063\u0072\u0065\u0061\u0074\u0069\u006F\u006E\u0054\u0069\u006D\u0065 = \u0053\u0061\u0076\u0065\u0052\u0065\u0073\u0074\u006F\u0072\u0065.\u0053\u0061\u0076\u0065\u0043\u0072\u0065\u0061\u0074\u0065\u0064\u0054\u0069\u006D\u0065;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079> \u0063\u0061\u0063\u0068\u0065 = \u006E\u0065\u0077 \u0044\u0069\u0063\u0074\u0069\u006F\u006E\u0061\u0072\u0079<\u0073\u0074\u0072\u0069\u006E\u0067, \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079>();                        [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0075\u0062\u006C\u0069\u0063 \u0062\u006F\u006F\u006C \u006E\u0065\u0065\u0064\u0057\u0069\u0070\u0065 => \u0064\u0069ff\u0065\u0072\u0065\u006E\u0074\u0043\u0072\u0065\u0061\u0074\u0069\u006F\u006E\u0044\u0061\u0074\u0065\u0073;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0075\u0062\u006C\u0069\u0063 \u0062\u006F\u006F\u006C \u006E\u0065\u0065\u0064\u0043\u006C\u0065\u0061\u006E\u0075\u0070 => \u0076\u0061\u006C\u0075\u0065\u0073.\u0043\u006F\u0075\u006E\u0074 > \u006D\u0069\u006E\u0069\u006D\u0061\u006C\u004C\u0069\u006D\u0069\u0074\u0046\u006F\u0072\u0043\u006C\u0065\u0061\u006E\u0075\u0070;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0062\u006F\u006F\u006C \u0064\u0069ff\u0065\u0072\u0065\u006E\u0074\u0043\u0072\u0065\u0061\u0074\u0069\u006F\u006E\u0044\u0061\u0074\u0065\u0073 => (\u0053\u0061\u0076\u0065\u0052\u0065\u0073\u0074\u006F\u0072\u0065.\u0053\u0061\u0076\u0065\u0043\u0072\u0065\u0061\u0074\u0065\u0064\u0054\u0069\u006D\u0065 - \u0063\u0072\u0065\u0061\u0074\u0069\u006F\u006E\u0054\u0069\u006D\u0065).\u0054\u006F\u0074\u0061\u006C\u0048\u006F\u0075\u0072\u0073 > 1;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0069\u006E\u0074 \u0063\u0061\u0063\u0068\u0065\u004C\u0069f\u0065\u0053\u0070\u0061\u006E => 300;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0075\u0062\u006C\u0069\u0063 \u0073\u0074\u0061\u0074\u0069\u0063 \u0069\u006E\u0074 \u0075\u006E\u0075\u0073\u0065\u0064\u0044\u0061\u0074\u0061\u004C\u0069f\u0065\u0053\u0070\u0061\u006E\u0044\u0061\u0079\u0073 => 14;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0069\u006E\u0074 \u006D\u0069\u006E\u0069\u006D\u0061\u006C\u004C\u0069\u006D\u0069\u0074\u0046\u006F\u0072\u0043\u006C\u0065\u0061\u006E\u0075\u0070 => 500;            [\u004A\u0073\u006F\u006E\u0049\u0067\u006E\u006F\u0072\u0065] \u0070\u0075\u0062\u006C\u0069\u0063 \u0069\u006E\u0074 \u0076\u0061\u006C\u0075\u0065\u0073\u0043\u006F\u0075\u006E\u0074 => \u0076\u0061\u006C\u0075\u0065\u0073.\u0043\u006F\u0075\u006E\u0074;                        \u0070\u0075\u0062\u006C\u0069\u0063 \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079 \u0047\u0065\u0074(\u006F\u0062\u006A\u0065\u0063\u0074 \u0070\u0061\u0072\u0061\u006D, \u0062\u006F\u006F\u006C \u0063\u0072\u0065\u0061\u0074\u0065\u004E\u0065\u0077\u004F\u006E\u004D\u0069\u0073\u0073\u0069\u006E\u0067)            {                \u0076\u0061\u0072 \u006B\u0065\u0079 = \u0047\u0065\u0074\u004B\u0065\u0079\u0046\u0072\u006F\u006D(\u0070\u0061\u0072\u0061\u006D);                \u0069f (\u0073\u0074\u0072\u0069\u006E\u0067.\u0049\u0073\u004E\u0075\u006C\u006C\u004F\u0072\u0045\u006D\u0070\u0074\u0079(\u006B\u0065\u0079) == \u0074\u0072\u0075\u0065)                {                    \u0072\u0065\u0074\u0075\u0072\u006E \u006E\u0075\u006C\u006C;                }                                \u0076\u0061\u0072 \u0076\u0061\u006C\u0075\u0065 = (\u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079) \u006E\u0075\u006C\u006C;                \u0069f (\u0063\u0061\u0063\u0068\u0065\u004C\u0069f\u0065\u0053\u0070\u0061\u006E > 0 && \u0063\u0061\u0063\u0068\u0065.\u0054\u0072\u0079\u0047\u0065\u0074\u0056\u0061\u006C\u0075\u0065(\u006B\u0065\u0079, \u006F\u0075\u0074 \u0076\u0061\u006C\u0075\u0065) == \u0074\u0072\u0075\u0065)                {                    \u0072\u0065\u0074\u0075\u0072\u006E \u0076\u0061\u006C\u0075\u0065;                }                \u0069f (\u0076\u0061\u006C\u0075\u0065\u0073.\u0054\u0072\u0079\u0047\u0065\u0074\u0056\u0061\u006C\u0075\u0065(\u006B\u0065\u0079, \u006F\u0075\u0074 \u0076\u0061\u006C\u0075\u0065) == f\u0061\u006C\u0073\u0065 && \u0063\u0072\u0065\u0061\u0074\u0065\u004E\u0065\u0077\u004F\u006E\u004D\u0069\u0073\u0073\u0069\u006E\u0067 == \u0074\u0072\u0075\u0065)                {                    \u0076\u0061\u006C\u0075\u0065 = \u006E\u0065\u0077 \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079();                    \u0076\u0061\u006C\u0075\u0065\u0073.\u0041\u0064\u0064(\u006B\u0065\u0079, \u0076\u0061\u006C\u0075\u0065);                }                \u0069f (\u0076\u0061\u006C\u0075\u0065 != \u006E\u0075\u006C\u006C)                {                    \u0076\u0061\u006C\u0075\u0065.\u004D\u0061\u0072\u006B\u0055\u0073\u0065\u0064();                    \u0069f (\u0063\u0061\u0063\u0068\u0065\u004C\u0069f\u0065\u0053\u0070\u0061\u006E > 0)                    {                        \u0063\u0061\u0063\u0068\u0065.\u0054\u0072\u0079\u0041\u0064\u0064(\u006B\u0065\u0079, \u0076\u0061\u006C\u0075\u0065);                    }                }                                \u0072\u0065\u0074\u0075\u0072\u006E \u0076\u0061\u006C\u0075\u0065;            }                        \u0070\u0075\u0062\u006C\u0069\u0063 \u0076\u006F\u0069\u0064 \u0053\u0065\u0074(\u006F\u0062\u006A\u0065\u0063\u0074 \u0070\u0061\u0072\u0061\u006D, \u0044\u0061\u0074\u0061\u0045\u006E\u0074\u0072\u0079 \u0076\u0061\u006C\u0075\u0065)            {                \u0076\u0061\u0072 \u006B\u0065\u0079 = \u0047\u0065\u0074\u004B\u0065\u0079\u0046\u0072\u006F\u006D(\u0070\u0061\u0072\u0061\u006D);                \u0069f (\u0073\u0074\u0072\u0069\u006E\u0067.\u0049\u0073\u004E\u0075\u006C\u006C\u004F\u0072\u0045\u006D\u0070\u0074\u0079(\u006B\u0065\u0079) == \u0074\u0072\u0075\u0065)                {                    \u0072\u0065\u0074\u0075\u0072\u006E;                }                \u0069f (\u0076\u0061\u006C\u0075\u0065 == \u006E\u0075\u006C\u006C)                {                    \u0069f (\u0076\u0061\u006C\u0075\u0065\u0073.\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0073\u004B\u0065\u0079(\u006B\u0065\u0079) == \u0074\u0072\u0075\u0065)                    {                        \u0076\u0061\u006C\u0075\u0065\u0073.\u0052\u0065\u006D\u006F\u0076\u0065(\u006B\u0065\u0079);                    }                                        \u0069f (\u0063\u0061\u0063\u0068\u0065.\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0073\u004B\u0065\u0079(\u006B\u0065\u0079) == \u0074\u0072\u0075\u0065)                    {                        \u0063\u0061\u0063\u0068\u0065.\u0052\u0065\u006D\u006F\u0076\u0065(\u006B\u0065\u0079);                    }                }                \u0065\u006C\u0073\u0065                {                    \u0069f (\u0076\u0061\u006C\u0075\u0065\u0073.\u0054\u0072\u0079\u0041\u0064\u0064(\u006B\u0065\u0079, \u0076\u0061\u006C\u0075\u0065) == f\u0061\u006C\u0073\u0065)                    {                        \u0076\u0061\u006C\u0075\u0065\u0073[\u006B\u0065\u0079] = \u0076\u0061\u006C\u0075\u0065;                                            \u0069f (\u0063\u0061\u0063\u0068\u0065.\u0043\u006F\u006E\u0074\u0061\u0069\u006E\u0073\u004B\u0065\u0079(\u006B\u0065\u0079) == \u0074\u0072\u0075\u0065)                        {                            \u0063\u0061\u0063\u0068\u0065[\u006B\u0065\u0079] = \u0076\u0061\u006C\u0075\u0065;                        }                    }                }            }            \u0070\u0075\u0062\u006C\u0069\u0063 \u0076\u006F\u0069\u0064 \u0043\u006C\u0065\u0061\u006E\u0075\u0070()            {                \u0076\u0061\u0072 \u006B\u0065\u0079\u0073 = \u006E\u0065\u0077 \u004C\u0069\u0073\u0074<\u0073\u0074\u0072\u0069\u006E\u0067>();                f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0070\u0061\u0069\u0072 \u0069\u006E \u0076\u0061\u006C\u0075\u0065\u0073)                {                    \u0076\u0061\u0072 \u006B\u0065\u0079 = \u0070\u0061\u0069\u0072.\u004B\u0065\u0079;                    \u0076\u0061\u0072 \u0076\u0061\u006C\u0075\u0065 = \u0070\u0061\u0069\u0072.\u0056\u0061\u006C\u0075\u0065;                                        \u0069f (\u0076\u0061\u006C\u0075\u0065.\u0064\u0061\u0079\u0073\u0053\u0069\u006E\u0063\u0065\u004C\u0061\u0073\u0074\u0055\u0073\u0065 > \u0075\u006E\u0075\u0073\u0065\u0064\u0044\u0061\u0074\u0061\u004C\u0069f\u0065\u0053\u0070\u0061\u006E\u0044\u0061\u0079\u0073)                    {                        \u006B\u0065\u0079\u0073.\u0041\u0064\u0064(\u006B\u0065\u0079);                    }                }                f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u006B\u0065\u0079 \u0069\u006E \u006B\u0065\u0079\u0073)                {                    \u0053\u0065\u0074(\u006B\u0065\u0079, \u006E\u0075\u006C\u006C);                }            }            \u0070\u0075\u0062\u006C\u0069\u0063 \u0076\u006F\u0069\u0064 \u0052\u0065\u0073\u0065\u0074\u0043\u0061\u0063\u0068\u0065()            {                \u0063\u0061\u0063\u0068\u0065.\u0043\u006C\u0065\u0061\u0072();            }            \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067 \u0047\u0065\u0074\u004B\u0065\u0079\u0046\u0072\u006F\u006D(\u006F\u0062\u006A\u0065\u0063\u0074 \u006F\u0062\u006A)            {                \u0069f (\u006F\u0062\u006A == \u006E\u0075\u006C\u006C)                {                    \u0072\u0065\u0074\u0075\u0072\u006E \u006E\u0075\u006C\u006C;                }                \u0069f (\u006F\u0062\u006A \u0069\u0073 \u0073\u0074\u0072\u0069\u006E\u0067)                {                    \u0072\u0065\u0074\u0075\u0072\u006E \u006F\u0062\u006A \u0061\u0073 \u0073\u0074\u0072\u0069\u006E\u0067;                }                \u0069f (\u006F\u0062\u006A \u0069\u0073 \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072)                {                    \u0072\u0065\u0074\u0075\u0072\u006E (\u006F\u0062\u006A \u0061\u0073 \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072).\u0055\u0073\u0065\u0072\u0049\u0044\u0053\u0074\u0072\u0069\u006E\u0067;                }                \u0069f (\u006F\u0062\u006A \u0069\u0073 \u0042\u0061\u0073\u0065\u004E\u0065\u0074\u0077\u006F\u0072\u006B\u0061\u0062\u006C\u0065)                {                    \u0072\u0065\u0074\u0075\u0072\u006E (\u006F\u0062\u006A \u0061\u0073 \u0042\u0061\u0073\u0065\u004E\u0065\u0074\u0077\u006F\u0072\u006B\u0061\u0062\u006C\u0065).\u006E\u0065\u0074?.\u0049\u0044.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();                }                \u0072\u0065\u0074\u0075\u0072\u006E \u006F\u0062\u006A.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u004C\u006F\u0061\u0064\u0044\u0061\u0074\u0061()        {            \u0074\u0072\u0079            {                \u0044\u0061\u0074\u0061 = \u0049\u006E\u0074\u0065\u0072f\u0061\u0063\u0065.\u004F\u0078\u0069\u0064\u0065.\u0044\u0061\u0074\u0061\u0046\u0069\u006C\u0065\u0053\u0079\u0073\u0074\u0065\u006D.\u0052\u0065\u0061\u0064\u004F\u0062\u006A\u0065\u0063\u0074<\u0050\u006C\u0075\u0067\u0069\u006E\u0044\u0061\u0074\u0061>($"{\u0064\u0061\u0074\u0061\u0046\u0069\u006C\u0065\u006E\u0061\u006D\u0065}");                                \u0069f (\u0044\u0061\u0074\u0061.\u006E\u0065\u0065\u0064\u0057\u0069\u0070\u0065 == \u0074\u0072\u0075\u0065)                {                    \u0049\u006E\u0074\u0065\u0072f\u0061\u0063\u0065.\u004F\u0078\u0069\u0064\u0065.\u0044\u0061\u0074\u0061\u0046\u0069\u006C\u0065\u0053\u0079\u0073\u0074\u0065\u006D.\u0057\u0072\u0069\u0074\u0065\u004F\u0062\u006A\u0065\u0063\u0074($"{\u0064\u0061\u0074\u0061\u0046\u0069\u006C\u0065\u006E\u0061\u006D\u0065}_\u006F\u006C\u0064", \u0044\u0061\u0074\u0061);                    \u0044\u0061\u0074\u0061 = \u006E\u0065\u0077 \u0050\u006C\u0075\u0067\u0069\u006E\u0044\u0061\u0074\u0061();                    \u0050\u0072\u0069\u006E\u0074\u0057\u0061\u0072\u006E\u0069\u006E\u0067($"\u0044\u0061\u0074\u0061 \u0077\u0061\u0073 \u0077\u0069\u0070\u0065\u0064 \u0062\u0079 \u0061\u0075\u0074\u006F-\u0077\u0069\u0070\u0069\u006E\u0067 f\u0075\u006E\u0063\u0074\u0069\u006F\u006E (\u004F\u006C\u0064: {\u0044\u0061\u0074\u0061.\u0063\u0072\u0065\u0061\u0074\u0069\u006F\u006E\u0054\u0069\u006D\u0065}, \u004E\u0065\u0077: {\u0053\u0061\u0076\u0065\u0052\u0065\u0073\u0074\u006F\u0072\u0065.\u0053\u0061\u0076\u0065\u0043\u0072\u0065\u0061\u0074\u0065\u0064\u0054\u0069\u006D\u0065})");                }                \u0069f (\u0044\u0061\u0074\u0061.\u006E\u0065\u0065\u0064\u0043\u006C\u0065\u0061\u006E\u0075\u0070 == \u0074\u0072\u0075\u0065)                {                    \u0076\u0061\u0072 \u006F\u006C\u0064\u0043\u006F\u0075\u006E\u0074 = \u0044\u0061\u0074\u0061.\u0076\u0061\u006C\u0075\u0065\u0073\u0043\u006F\u0075\u006E\u0074;                    \u0044\u0061\u0074\u0061.\u0043\u006C\u0065\u0061\u006E\u0075\u0070();                    \u0076\u0061\u0072 \u006E\u0065\u0077\u0043\u006F\u0075\u006E\u0074 = \u0044\u0061\u0074\u0061.\u0076\u0061\u006C\u0075\u0065\u0073\u0043\u006F\u0075\u006E\u0074;                    \u0050\u0072\u0069\u006E\u0074\u0057\u0061\u0072\u006E\u0069\u006E\u0067($"\u0052\u0065\u006D\u006F\u0076\u0065\u0064 {\u006F\u006C\u0064\u0043\u006F\u0075\u006E\u0074 - \u006E\u0065\u0077\u0043\u006F\u0075\u006E\u0074} \u0076\u0061\u006C\u0075\u0065\u0073 \u0074\u0068\u0061\u0074 \u0061\u0072\u0065 \u006F\u006C\u0064\u0065\u0072 \u0074\u0068\u0061\u006E {\u0050\u006C\u0075\u0067\u0069\u006E\u0044\u0061\u0074\u0061.\u0075\u006E\u0075\u0073\u0065\u0064\u0044\u0061\u0074\u0061\u004C\u0069f\u0065\u0053\u0070\u0061\u006E\u0044\u0061\u0079\u0073} \u0064\u0061\u0079\u0073 (\u0057\u0061\u0073: {\u006F\u006C\u0064\u0043\u006F\u0075\u006E\u0074}, \u004E\u006F\u0077: {\u006E\u0065\u0077\u0043\u006F\u0075\u006E\u0074})");                }                \u0064\u0061\u0074\u0061\u0056\u0061\u006C\u0069\u0064 = \u0074\u0072\u0075\u0065;                \u0074\u0069\u006D\u0065\u0072.\u0045\u0076\u0065\u0072\u0079(\u0043\u006F\u0072\u0065.\u0052\u0061\u006E\u0064\u006F\u006D.\u0052\u0061\u006E\u0067\u0065(500, 700), \u0053\u0061\u0076\u0065\u0044\u0061\u0074\u0061);                \u0053\u0061\u0076\u0065\u0044\u0061\u0074\u0061();            }            \u0063\u0061\u0074\u0063\u0068 (\u0045\u0078\u0063\u0065\u0070\u0074\u0069\u006F\u006E \u0065)            {                \u0044\u0061\u0074\u0061 = \u006E\u0065\u0077 \u0050\u006C\u0075\u0067\u0069\u006E\u0044\u0061\u0074\u0061();                \u0064\u0061\u0074\u0061\u0056\u0061\u006C\u0069\u0064 = f\u0061\u006C\u0073\u0065;                f\u006F\u0072 (\u0076\u0061\u0072 \u0069 = 0; \u0069 < 5; \u0069++)                {                    \u0050\u0072\u0069\u006E\u0074\u0045\u0072\u0072\u006F\u0072("!!! \u0043\u0052\u0049\u0054\u0049\u0043\u0041\u004C \u0044\u0041\u0054\u0041 \u0045\u0052\u0052\u004F\u0052 !!!\n * \u0044\u0061\u0074\u0061 \u0077\u0061\u0073 \u006E\u006F\u0074 \u006C\u006F\u0061\u0064\u0065\u0064!\n * \u0044\u0061\u0074\u0061 \u0061\u0075\u0074\u006F-\u0073\u0061\u0076\u0065 \u0077\u0061\u0073 \u0064\u0069\u0073\u0061\u0062\u006C\u0065\u0064!");                }                                \u004C\u006F\u0067\u0054\u006F\u0046\u0069\u006C\u0065("\u0065\u0072\u0072\u006F\u0072\u0073", $"\n\n\u0045\u0072\u0072\u006F\u0072: {\u0065.\u004D\u0065\u0073\u0073\u0061\u0067\u0065}\n\n\u0054\u0072\u0061\u0063\u0065: {\u0065.\u0053\u0074\u0061\u0063\u006B\u0054\u0072\u0061\u0063\u0065}\n\n", \u0074\u0068\u0069\u0073);            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0053\u0061\u0076\u0065\u0044\u0061\u0074\u0061()        {            \u0069f (\u0044\u0061\u0074\u0061 != \u006E\u0075\u006C\u006C && \u0064\u0061\u0074\u0061\u0056\u0061\u006C\u0069\u0064 == \u0074\u0072\u0075\u0065)            {                \u0044\u0061\u0074\u0061.\u0052\u0065\u0073\u0065\u0074\u0043\u0061\u0063\u0068\u0065();                \u0049\u006E\u0074\u0065\u0072f\u0061\u0063\u0065.\u004F\u0078\u0069\u0064\u0065.\u0044\u0061\u0074\u0061\u0046\u0069\u006C\u0065\u0053\u0079\u0073\u0074\u0065\u006D.\u0057\u0072\u0069\u0074\u0065\u004F\u0062\u006A\u0065\u0063\u0074(\u0064\u0061\u0074\u0061\u0046\u0069\u006C\u0065\u006E\u0061\u006D\u0065, \u0044\u0061\u0074\u0061);            }        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006C\u0061\u0073\u0073 \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079        {            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067 \u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0050\u0072\u0069\u006F\u0072\u0069\u0074\u0079")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0069\u006E\u0074 \u0070\u0072\u0069\u006F\u0072\u0069\u0074\u0079;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0053\u0069\u007A\u0065")]             \u0070\u0075\u0062\u006C\u0069\u0063 \u0069\u006E\u0074 \u0073\u0069\u007A\u0065;            [\u004A\u0073\u006F\u006E\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079(\u0050\u0072\u006F\u0070\u0065\u0072\u0074\u0079\u004E\u0061\u006D\u0065 = "\u0043\u006F\u006F\u006C\u0064\u006F\u0077\u006E")]            \u0070\u0075\u0062\u006C\u0069\u0063 \u0069\u006E\u0074 \u0063\u006F\u006F\u006C\u0064\u006F\u0077\u006E;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079 \u0047\u0065\u0074\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E(\u0075\u006C\u006F\u006E\u0067 \u0070\u006C\u0061\u0079\u0065\u0072\u0049\u0044, \u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079[] \u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073)        {            \u0076\u0061\u0072 \u0076\u0061\u006C\u0075\u0065 = (\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0045\u006E\u0074\u0072\u0079) \u006E\u0075\u006C\u006C;            \u0076\u0061\u0072 \u0069\u0064\u0053\u0074\u0072\u0069\u006E\u0067 = \u0070\u006C\u0061\u0079\u0065\u0072\u0049\u0044.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();            \u0076\u0061\u0072 \u006E\u0075\u006D = -1;            f\u006F\u0072\u0065\u0061\u0063\u0068 (\u0076\u0061\u0072 \u0065\u006E\u0074\u0072\u0079 \u0069\u006E \u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073)            {                \u0069f (\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E.\u0055\u0073\u0065\u0072\u0048\u0061\u0073\u0050\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E(\u0069\u0064\u0053\u0074\u0072\u0069\u006E\u0067, \u0065\u006E\u0074\u0072\u0079.\u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E) && \u0065\u006E\u0074\u0072\u0079.\u0070\u0072\u0069\u006F\u0072\u0069\u0074\u0079 > \u006E\u0075\u006D)                {                    \u006E\u0075\u006D = \u0065\u006E\u0074\u0072\u0079.\u0070\u0072\u0069\u006F\u0072\u0069\u0074\u0079;                    \u0076\u0061\u006C\u0075\u0065 = \u0065\u006E\u0074\u0072\u0079;                }            }            \u0069f (\u0070\u006C\u0061\u0079\u0065\u0072\u0049\u0044.\u0049\u0073\u0053\u0074\u0065\u0061\u006D\u0049\u0064() == f\u0061\u006C\u0073\u0065)            {                \u0076\u0061\u006C\u0075\u0065 = \u0070\u0065\u0072\u006D\u0069\u0073\u0073\u0069\u006F\u006E\u0073.\u0046\u0069\u0072\u0073\u0074\u004F\u0072\u0044\u0065f\u0061\u0075\u006C\u0074();            }            \u0072\u0065\u0074\u0075\u0072\u006E \u0076\u0061\u006C\u0075\u0065;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0063\u006C\u0061\u0073\u0073 \u0050\u0065\u006E\u0064\u0069\u006E\u0067\u0054\u0072\u0061\u0064\u0065 : \u004D\u006F\u006E\u006F\u0042\u0065\u0068\u0061\u0076\u0069\u006F\u0075\u0072        {            \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072;            \u0070\u0075\u0062\u006C\u0069\u0063 \u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0063\u0061\u006C\u006C\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072;            \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0041\u0077\u0061\u006B\u0065()            {                \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072 = \u0047\u0065\u0074\u0043\u006F\u006D\u0070\u006F\u006E\u0065\u006E\u0074<\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072>();            }            \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0076\u006F\u0069\u0064 \u0053\u0074\u0061\u0072\u0074()            {                \u0052\u0075\u006E\u0045ff\u0065\u0063\u0074(\u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072.\u0074\u0072\u0061\u006E\u0073f\u006F\u0072\u006D.\u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E, \u0063\u006F\u006Ef\u0069\u0067.\u0065ff\u0065\u0063\u0074\u004F\u006E\u0052\u0065\u0071\u0075\u0065\u0073\u0074, \u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072);                \u0052\u0075\u006E\u0045ff\u0065\u0063\u0074(\u0063\u0061\u006C\u006C\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072.\u0074\u0072\u0061\u006E\u0073f\u006F\u0072\u006D.\u0070\u006F\u0073\u0069\u0074\u0069\u006F\u006E, \u0063\u006F\u006Ef\u0069\u0067.\u0065ff\u0065\u0063\u0074\u004F\u006E\u0052\u0065\u0071\u0075\u0065\u0073\u0074, \u0063\u0061\u006C\u006C\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072);                \u0049\u006E\u0076\u006F\u006B\u0065(\u006E\u0061\u006D\u0065\u006Ff(\u0054\u0069\u006D\u0065\u0064\u0044\u0065\u0073\u0074\u0072\u006F\u0079), 30f);            }            \u0070\u0075\u0062\u006C\u0069\u0063 \u0076\u006F\u0069\u0064 \u0053\u0065\u0074\u0075\u0070(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u00762)            {                \u0063\u0061\u006C\u006C\u0065\u0072\u0050\u006C\u0061\u0079\u0065\u0072 = \u00762;            }            \u0070\u0075\u0062\u006C\u0069\u0063 \u0076\u006F\u0069\u0064 \u0054\u0069\u006D\u0065\u0064\u0044\u0065\u0073\u0074\u0072\u006F\u0079()            {                \u0044\u0065\u0073\u0074\u0072\u006F\u0079(\u0074\u0068\u0069\u0073);                \u0070\u006C\u0075\u0067\u0069\u006E.\u0053\u0065\u006E\u0064\u004D\u0065\u0073\u0073\u0061\u0067\u0065(\u0074\u0061\u0072\u0067\u0065\u0074\u0050\u006C\u0061\u0079\u0065\u0072, \u004D\u0065\u0073\u0073\u0061\u0067\u0065\u0054\u0079\u0070\u0065.\u0054\u0072\u0061\u0064\u0065\u0043\u0061\u006E\u0063\u0065\u006C\u006C\u0065\u0064);            }        }        [\u0050\u006C\u0075\u0067\u0069\u006E\u0052\u0065f\u0065\u0072\u0065\u006E\u0063\u0065] \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0050\u006C\u0075\u0067\u0069\u006E \u004E\u006F\u0045\u0073\u0063\u0061\u0070\u0065;        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0062\u006F\u006F\u006C \u0049\u006E\u0052\u0061\u0069\u0064\u0042\u006C\u006F\u0063\u006B(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072)        {            \u0072\u0065\u0074\u0075\u0072\u006E \u004E\u006F\u0045\u0073\u0063\u0061\u0070\u0065?.\u0043\u0061\u006C\u006C<\u0062\u006F\u006F\u006C>("\u0049\u0073\u0052\u0061\u0069\u0064\u0042\u006C\u006F\u0063\u006B\u0065\u0064", \u0070\u006C\u0061\u0079\u0065\u0072) ?? f\u0061\u006C\u0073\u0065;        }        \u0070\u0072\u0069\u0076\u0061\u0074\u0065 \u0073\u0074\u0061\u0074\u0069\u0063 \u0073\u0074\u0072\u0069\u006E\u0067 \u0043\u0061\u006E\u0055\u0073\u0065\u0054\u0072\u0061\u0064\u0065(\u0042\u0061\u0073\u0065\u0050\u006C\u0061\u0079\u0065\u0072 \u0070\u006C\u0061\u0079\u0065\u0072)        {            \u0076\u0061\u0072 \u0072\u0065\u0073\u0075\u006C\u0074 = \u0049\u006E\u0074\u0065\u0072f\u0061\u0063\u0065.\u0043\u0061\u006C\u006C\u0048\u006F\u006F\u006B("\u0043\u0061\u006E\u0054\u0072\u0061\u0064\u0065", \u0070\u006C\u0061\u0079\u0065\u0072);            \u0072\u0065\u0074\u0075\u0072\u006E \u0072\u0065\u0073\u0075\u006C\u0074?.\u0054\u006F\u0053\u0074\u0072\u0069\u006E\u0067();        }    }}